\label{thm-b-char}
Let $n,k\geq1$. Then
\begin{subequations}
\begin{equation}
    \label{thm-type-b-0-char}
    P_{(k^n)}^{\mathrm{B}_n}(X;t,0)=\sum_{y \in \mathbb{Z}^k}
(-1)^{|y| + \operatorname{inv}(\nu)}
t^{\sum_{j=1}^k \left( (k+\frac{1}{2}) y_j^2 + (j-\frac{1}{2})y_j \right)} 
so_{\lambda(\nu)}(X),
\end{equation}
where $K=2k+1$ and $\nu_a = |Ky_a+a|-[y_a\ge0]$ for $a=1,\dots,k$;
\begin{equation}
\label{thm-type-b-t-char}
P_{(k^n)}^{\mathrm{B}_n}(X;t,-t^{1/2})=\sum_{y\in\mathbb{Z}^k}
(-1)^{\operatorname{inv}(\nu)}
t^{\sum_{j=1}^k \left( ky_j^2 + (j-\frac{1}{2})y_j \right)}
so_{\lambda(\nu)}(X),
\end{equation}
where $K=2k$ and $\nu_a = |Ky_a + a| - [y_a\ge0]$ for $a=1,\dots,k$;
and
    \begin{equation}
\label{thm-type-b-1-char}
     P_{(k^n)}^{\mathrm{B}_n}(X;t,1)=
\sum_{y \in \mathbb{Z}^k}
(-1)^{|y|+\mathrm{inv}(\nu)}
t^{\sum_{j=1}^k \left(k y_j^2 + (j-1)y_j \right)}
o^{\textup{even}}_{\lambda(\nu)}(X),
    \end{equation}
\end{subequations}
where $K=2k$ and $\nu_a = |Ky_a + a-1|$ for $a = 1,\ldots,k$.
In each sum, the entries of $\nu$ are required to be distinct and to lie in $\{0,\ldots,n+k-1\}$.

\label{cor-b}
Let $n,k\geq1$. Then
\begin{subequations}
\begin{equation}
    \label{thm-b-0}
    P_{(k^n)}^{\mathrm{B}_n}(X;t,0)=\sum_{y \in \mathbb{Z}^k}
\det_{1 \le i,j \le k}
\left(
(-1)^{y_i}
t^{\frac{1}{2} K y_i^2 - (j-\frac{1}{2})y_i}
\left(
\dot{e}_{\,n-i+j-K y_i}
+
\dot{e}_{\,n+i+j- Ky_i-1}
\right)
\right),
\end{equation}
where $K=2k+1$, as well as
\begin{equation}
\label{thm-type-b-t}
 P_{(k^n)}^{\mathrm{B}_n}(X;t,-t^{1/2})=\sum_{y \in \mathbb{Z}^k}
\det_{1 \le i,j \le k}
\left(
t^{\frac{1}{2} K y_i^2 - (j-\frac{1}{2})y_i}
\left(
\dot{e}_{\,n-i+j-K y_i}
+
\dot{e}_{\,n+i+j- Ky_i-1}
\right)
\right)\,,
\end{equation}
and
    \begin{equation}
\label{thm-type-b-1}
     P_{(k^n)}^{\mathrm{B}_n}(X;t,1)=
\frac{1}{2}
\sum_{y \in \mathbb{Z}^k}
\det_{1 \le i,j \le k}
\left(
(-1)^{y_i}
t^{\frac{1}{2}K y_i^2 - (j-1)y_i}
(
\dot{e}_{\,n-i+j-K y_i}
+
\dot{e}_{\,n+i+j- Ky_i-2})
\right),
    \end{equation}
\end{subequations}
where $K=2k$.

\label{main-type-c}
Let $n,k\geq1$. Then
\begin{subequations}
\begin{equation}
        \label{thm-type-c-0-char}
    P_{(k^n)}^{\mathrm{C}_n}(X;t,0)=
\sum_{y \in \mathbb{Z}^{k}}
(-1)^{\mathrm{inv}(\nu)+\sum_{j=1}^k [y_j<0]}
t^{\sum_{j=1}^k \left(\frac{1}{2}Ky_j^2 + jy_j \right)}
sp_{\lambda(\nu)}(X),
    \end{equation}
    where $K=2k+2$ and $\nu_a = |Ky_a + a| - 1$ for $a=1,\dots,k$, and
    \begin{equation}
\label{thm-type-c-t-char}
    P_{(k^n)}^{\mathrm{C}_n}(X;t,t)=
\sum_{\substack{y \in \mathbb{Z}^{k}\\ y_k\ge0}}
(-1)^{|y|+\mathrm{inv}(\nu)+\sum_{j=1}^k [y_j<0]}
t^{\sum_{j=1}^k \left( \frac{1}{2}Ky_j^2 + jy_j \right)}
sp_{\lambda(\nu)}(X),
\end{equation}
\end{subequations}
where $K=2k$ and $\nu_a = |Ky_a + a|-1$ for $a=1,\dots,k$.
In each sum, the entries of $\nu$ are required to be distinct and to lie in $\{0,\ldots,n+k-1\}$.

\label{cor-type-c}
Let $n,k\geq1$. Then
\begin{subequations}
\begin{equation}
     \label{cor-type-c-0}
P_{(k^n)}^{\mathrm{C}_n}(X;t,0)=\sum_{y \in \mathbb{Z}^k}
\det_{1 \le i,j \le k}
\left(
t^{\frac{1}{2} K y_i^2 - jy_i}
\left(
\dot{e}_{\,n-i+j-K y_i}
-
\dot{e}_{\,n+i+j- Ky_i}
\right)
\right),
\end{equation}
where $K = 2k+2$.
Furthermore,
\begin{equation}
\label{cor-type-c-t}
P_{(k^n)}^{\mathrm{C}_n}(X;t,t)=
    \sum_{\substack{y \in \mathbb{Z}^k,\\ |y| \text{ even }}}
\det_{1 \le i,j \le k}
\left(
t^{\frac{1}{2} K y_i^2 - jy_i}
\left(
\dot{e}_{\,n-i+j-K y_i}
-
\dot{e}_{\,n+i+j- Ky_i}
\right)
\right),
\end{equation}
\end{subequations}
    where $K=2k$.

\label{thm-type-bc-0-char-all}
Let $n,k\geq1$. Then
\begin{equation}
\label{thm-type-bc-0-char}
        P_{(k^n)}^{\mathrm{BC}_n}(X;t,-t^{1/2},0)=
\sum_{y \in \mathbb{Z}^{k}}
(-1)^{|y| + \mathrm{inv}(\nu)+ \sum_{j=1}^k [y_j<0]}
t^{\sum_{j=1}^k \left( \frac{1}{2}Ky_j^2 + jy_j \right)}
sp_{\lambda(\nu)}(X),
    \end{equation}
    where $K=2k+1$ and $\nu_a = |Ky_a+a|-1$ for $a=1,\ldots,k$.
In the sum, the entries of $\nu$ are required to be distinct and to lie in $\{0,\ldots,n+k-1\}$.

\label{cor-type-bc}
Let $n,k\geq1$. Then
\begin{equation}
\label{cor-type-bc-0}
        P_{(k^n)}^{\mathrm{BC}_n}(X;t,-t^{1/2},0)=
    \sum_{y \in \mathbb{Z}^k}
\det_{1 \le i,j \le k} 
\left(
(-1)^{y_i}
t^{\frac{1}{2} K y_i^2 - jy_i}
\left(
\dot{e}_{\,n-i+j-K y_i}
-
\dot{e}_{\,n+i+j- Ky_i}
\right)
\right),
    \end{equation}
    where $K=2k+1$.

Notice that 
\begin{equation}\label{too many rows}
s_\lambda(X) = sp_\lambda(X)  = so_\lambda(X) = o^{\textup{even}}_\lambda(X) = 0, \quad
\text{if } n < \ell(\lambda).
\end{equation}
We also use the convention that 
\begin{equation}\label{eq: convention not a partiton}
s_\lambda(X) = sp_\lambda(X)  = so_\lambda(X) = o^{\textup{even}}_\lambda(X) = 0, \quad
\text{if } \lambda \textrm{ is not a partition}.
\end{equation}

\label{magical manipulation}
Let $n,k\in\mathbb{Z}_{>0}$. The (multiparameter) Hall--Littlewood polynomial of type $\mathrm{BC}_n$ indexed by a rectangular partition satisfies
    \begin{multline*}
    P_{(k^n)}^{\mathrm{BC}_n}(X;t,s_1,s_2)= \frac{\sqrt{t}^{\binom{n}{2}}}{2}
    \prod_{i=1}^nx_i^{n-1}\prod_{1\leq i<j\leq n}\frac{1}{(1-x_ix_j)(x_i-x_j)}\\\times\det_{1\le i,j\le n}\left(\frac{(1-s_1x_i)(1-s_2x_i)}{1-x_i^2}
    ((\sqrt{t})^{j-1}x_i^{j-1-k}+
    (\sqrt{t})^{-j+1}x_i^{-j+1-k})\right.\\\left.-\frac{(s_1-x_i)(s_2-x_i)}{1-x_i^2}
    ((\sqrt{t})^{j-1}x_i^{-j+1+k}
    +(\sqrt{t})^{-j+1}x_i^{j-1+k})\right).
\end{multline*}

The underlying set of $\mathbb{Z}_2\wr S_n$ is $\mathbb{Z}_2^n\times S_n $.
Split the sum in the expression \eqref{eq:intro-bc-definition}
over the wreath product accordingly,
\begin{multline*}
    P_{(k^n)}^{\mathrm{BC}_n}(X;t,s_1,s_2) = \frac{1}{ v_{(k^n)}(t)} \\
    \times \sum_{\alpha \in \{\pm 1\}^n}\left[\sum_{\sigma\in S_n}\sigma.\!\left(\prod_{i=1}^n\bar{x}_i^{k}\frac{(1-s_1x_i)(1-s_2x_i)}{1-x_i^2}\prod_{1\leq i<j\leq n}\frac{(tx_i-x_j)(1-tx_ix_j)}{(x_i-x_j)(1-x_ix_j)}\right)\right]_{X=X^\alpha},
\end{multline*}
where we denote $X^\alpha=(x_1^{\alpha_1},\dots,x_n^{\alpha_n})$ for $\alpha\in \{\pm1\}^n$ and note that $v_{(k^n)}(t)= \prod_{i=1}^n \frac{1-t^i}{1-t}$.
We rewrite the sum over $S_n$ by factoring out terms that are invariant by permutations. The sum becomes
\begin{multline*}
    \prod_{i=1}^n\bar{x}_i^{k}\frac{(1-s_1x_i)(1-s_2x_i)}{1-x_i^2}\prod_{1\leq i<j\leq n}\frac{1-tx_ix_j}{1-x_ix_j}\sum_{\sigma\in S_n}\sigma.\!\left(\prod_{1\leq i<j\leq n}\frac{tx_i-x_j}{x_i-x_j}\right)\\
    =
    \prod_{i=1}^n\bar{x}_i^{k}\frac{(1-s_1x_i)(1-s_2x_i)}{1-x_i^2}\prod_{1\leq i<j\leq n}\frac{1-tx_ix_j}{1-x_ix_j}v_{(k^n)}(t) \,,
\end{multline*}
where we have used~\cite[p.~207, (1.4)]{Macdonald1995}. The right-most term cancels the prefactor $1/v_{(k^n)}(t)$ and we obtain the following formula for the Hall--Littlewood polynomial:
\[
    P_{(k^n)}^{\mathrm{BC}_n}(X;t,s_1,s_2) = \sum_{\alpha \in \{\pm 1\}^n}\left[\prod_{i=1}^n\bar{x}_i^{k}\frac{(1-s_1x_i)(1-s_2x_i)}{1-x_i^2}\prod_{1\leq i<j\leq n}\frac{1-tx_ix_j}{1-x_ix_j} \right]_{X=X^\alpha}.
\]


Now observe that for any $\alpha\in \{\pm1\}^n$ we have
\begin{equation*}
    \left[\prod_{1\leq i<j\leq n}\frac{1}{(x_i-x_j)(1-x_ix_j)}\right]_{X=X^\alpha}=\frac{\prod_{i\in\alpha^-}x_i^{2(n-1)}}{\prod_{1\leq i<j\leq n}(x_i-x_j)(1-x_ix_j)}\,,
\end{equation*}
where $\alpha^-=\{i\in [n]\mid \alpha_i=-1\}$. Dividing and multiplying the Hall--Littlewood polynomial by this expression gives
\begin{align*}
    P_{k^n}^{\mathrm{BC}_n}(X;&t,s_1,s_2)=\frac{1}{\prod_{1\leq i<j\leq n}(x_i-x_j)(1-x_ix_j)}\\
    &\times \sum_{\alpha \in \{\pm 1\}^n}
    \prod_{i\in\alpha^-}x_i^{2(n-1)}
    \left[\prod_{i=1}^n\bar{x}_i^{k}\frac{(1-s_1x_i)(1-s_2x_i)}{1-x_i^2}\prod_{1\leq i<j\leq n}
    {(1-tx_ix_j)}{(x_i-x_j)}\right]_{X
    =X^\alpha}\\& =
    \frac{\prod_{i=1}^n x_i^{n-1}}{\prod_{1\leq i<j\leq n}(x_i-x_j)(1-x_ix_j)}
    \\&\times\sum_{\alpha \in \{\pm 1\}^n}
    \left[\prod_{i=1}^n\bar{x}_i^{k+n-1}
    \frac{(1-s_1x_i)(1-s_2x_i)}{1-x_i^2}
    \prod_{1\leq i<j\leq n}(1-tx_ix_j)(x_i-x_j)\right]_{X=X^\alpha}.
\end{align*}
In the last equality we have used the following simplification,
\begin{multline*}
    \prod_{i\in\alpha^-} x_i^{2(n-1)}
\left[
\prod_{i=1}^n\bar{x}_i^{k}
\right]_{X=X^\alpha}
= \left(\prod_{i=1}^nx_i^{n-1}\prod_{i=1}^nx_i^{-n+1}\right)\prod_{i\in\alpha^-} x_i^{n-1}\prod_{i\in\alpha^-} x_i^{n-1}\left[
\prod_{i=1}^n\bar{x}_i^{k}
\right]_{X=X^\alpha}\\= \prod_{i=1}^nx_i^{n-1}\left(\prod_{i=1}^nx_i^{-n+1}\prod_{i\in\alpha^-} x_i^{n-1}\right)\prod_{i\in\alpha^-} x_i^{n-1}\left[
\prod_{i=1}^n\bar{x}_i^{k}
\right]_{X=X^\alpha}\\=\prod_{i=1}^nx_i^{n-1}\prod_{i\in\alpha^+} x_i^{-n+1}\prod_{i\in\alpha^-} x_i^{n-1}\left[
\prod_{i=1}^n\bar{x}_i^{k}
\right]_{X=X^\alpha}=\prod_{i=1}^n x_i^{n-1} \left[\prod_{i=1}^n\bar{x}_i^{k+n-1}\right]_{X=X^\alpha},
\end{multline*}
where we first multiply the equation with $1=\prod_{i=1}^nx_i^{n-1}\prod_{i=1}^nx_i^{-n+1}$, then regroup terms and use that $\alpha^{-}$ and $\alpha^+$ partition $[n]=\alpha^-\sqcup \alpha^+$ to get that $\prod_{i=1}^nx_i^{-n+1}\prod_{i\in\alpha^-} x_i^{n-1}=\prod_{i\in\alpha^+} x_i^{-n+1}$ and then use it once again to distribute the two factors over the expression in the square brackets in the last equality.

Setting $x_i=x_i\sqrt{t}$ in the Weyl denominator of type \ref{eq: Denom type D} we obtain
\begin{equation}
   \det_{1\leq i,j\leq n}\left(
    (x_i\sqrt{t})^{j-1}+  (\bar{x}_i/\sqrt{t})^{j-1}\right)= 2 (\sqrt{t})^{-\binom{n}{2}}
    \prod_{i=1}^n\bar{x}_i^{n-1}\prod_{1\leq i<j\leq n}(1-tx_ix_j)(x_i-x_j).
\end{equation}
We use this factorisation to find that $P_{k^n}^{\mathrm{BC}_n}(X;t,s_1,s_2)$ equals
\begin{multline*}
\frac{\sqrt{t}^{\binom{n}{2}}}{2}
    \prod_{i=1}^nx_i^{n-1}\prod_{1\leq i<j\leq n}\frac{1}{(1-x_ix_j)(x_i-x_j)}\\\times
\sum_{\alpha \in \{\pm 1\}^n}
    \left[\prod_{i=1}^n\bar{x}_i^{k}
    \frac{(1-s_1x_i)(1-s_2x_i)}{1-x_i^2}
    \det_{1\le i,j\le n}\left(
    (x_i\sqrt{t})^{j-1}+  (\bar{x}_i/\sqrt{t})^{j-1}\right)\right]_{X=X^\alpha}.
\end{multline*}
By linearity of the determinant this is equal to 
\begin{multline*}
 \frac{\sqrt{t}^{\binom{n}{2}}}{2}
    \prod_{i=1}^nx_i^{n-1}\prod_{1\leq i<j\leq n}\frac{1}{(1-x_ix_j)(x_i-x_j)}\\\times
    \det_{1\le i,j\le n}\left(
    \frac{(1-s_1x_i)(1-s_2x_i)}{1-x_i^2}
    (x_i^{j-1-k}(\sqrt{t})^{j-1}+  
    \bar{x}_i^{j-1+k}(\sqrt{t})^{-j+1})\right.
    \\\left.-
    \frac{(x_i-s_1)(x_i-s_2)}{1-x_i^2}
    (\bar{x}_i^{j-1-k}(\sqrt{t})^{j-1}+  
    x_i^{j-1+k}(\sqrt{t})^{-j+1})\right)
\end{multline*}
and thus we are finished.

\label{lem: Noodle-Doodle expansion first form}
Let $M$ be an $n\times(n-m)$ matrix, let $f_1,\ldots,f_n$ be functions
on $V$, and let $p_s,p_t$ be functions on $E$. Then
\begin{multline}\label{eq: to show pure graph}
 \det_{\substack{1\leq i\leq n\\ j\in E}}
 \bigl(M ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ p_t(j)f_i(t_{\mathcal N}(j))
                         +p_s(j)f_i(s_{\mathcal N}(j))\bigr)
 \\
 =\sum_{A\in\mathcal A(\Lambda_{m,k,h^+,h^-})}
   \prod_{j\in E\setminus E_A}p_t(j)
   \prod_{j\in E_A}p_s(j)
   \det_{\substack{1\leq i\leq n\\ j\in E}}
     \bigl(M ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ f_i(t_A(j))\bigr).
\end{multline}

\label{lem: EA and tA(j) are given by}
For an orientation $A\in \mathcal A(\Lambda_{m,k,h^+,h^-})$ determined by the roots $z_0,\dots,z_{\bar k}$ parametrised as in~\eqref{eq: parametrisation of roots}
and~\eqref{eq: admissible roots}, we have
\begin{equation}\label{eq: EA is given by}
 E_A=\bigcup_{i=0}^{\bar k}\Big\{K\ell+k+\alpha_i i+\lceil h^+-h^-\rceil
       -[y_i<0]\lceil|h^++h^-|\rceil~:~     0\leq\ell<|y_i|\Big\},
\end{equation}
where $\ell$ is an integer. Moreover,
\begin{equation}\label{eq: tA(j) is equal to}
 t_A(j)=\begin{cases}
 |k-j+h^+-h^-|,&j\in E_A,\\
 k+j+h^++h^-,&j\notin E_A,
 \end{cases}
 \qquad
 |E_A^2|=\sum_{i=0}^{\bar k}\bigl(|y_i|-[y_i<0]\bigr).
\end{equation}

\label{lem: column order}
For an orientation $A\in\mathcal A(\Lambda_{m,k,h^+,h^-})$ with roots $z_0,\ldots,z_{\bar k}$, set
\[
 b_j=\bigl|\{i:i>j\text{ and }z_i>z_j\}\bigr|.
\]
Then
\begin{equation}\label{eq: sign of column order}
 (-1)^{\operatorname{inv}(t_A(1),\ldots,t_A(m))}=(-1)^{\binom{\bar k+1}{2}
       +\sum_{j=0}^{\bar k}\bigl((K-1)y_j
            +2|h^++h^-|[y_j<0]+b_j\bigr)},
\end{equation}
where $\operatorname{inv}(a_1,\dots,a_n)\coloneqq|\{(i,j)\in[1,n]^2\mid i>j\textrm{ and }a_i<a_j\}|$ is the number of \emph{inversions} of the array $(a_1,\dots,a_n)$.

\label{lem: noodle-doodle expansion}
\label{thm: Noodle-Doodle expansion}
Let $M$ be an $n\times(n-m)$ matrix and let $\xi_1,\ldots,\xi_n$ be
functions on $\mathbb{Z}+|h^++h^-|$ satisfying
$\xi_i(a)=\epsilon\xi_i(-a)$ for a fixed $\epsilon\in\{\pm1\}$.
For arbitrary functions $p_+,p_-$ on $E$, we have
\begin{multline}\label{eq: general determinant expansion}
 \det_{\substack{1\leq i\leq n\\1\leq j\leq m}}
 \bigl(M ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ p_+(j)\xi_i(k+j+h^++h^-)
                         +p_-(j)\xi_i(k-j+h^+-h^-)\bigr)\\
 =\sum_{(y_0,\ldots,y_{\bar k})}
 \epsilon^{\sum_{j=0}^{\bar k}(|y_j|-[y_j<0])}
 (-1)^{\binom{\bar k+1}{2}+
     \sum_{j=0}^{\bar k}((K-1)y_j+2|h^++h^-|[y_j<0]+b_j)}\\
 \times\prod_{j\in E\setminus E_A}p_+(j)\prod_{j\in E_A}p_-(j)
 \det_{\substack{1\leq i\leq n\\v\in V\setminus\{z_0,\ldots,z_{\bar k}\}}}
       \bigl(M ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ \xi_i(v)\bigr).
\end{multline}
Here the sum ranges precisely over~\eqref{eq: admissible roots}, $E_A$ is
given by~\eqref{eq: EA is given by}, and $b_j$ is as in
Lemma~\ref{lem: column order}. The columns indexed by $v$ are in increasing
order.

\label{lem: noodle-doodle expansion 2.1a}
    Let $\eta_1,\dots,\eta_n$ be functions on $\frac{1}{2}\mathbb{Z}$ with $\eta_i(a) = -\eta_i(-a)$. 
    Then
    \begin{multline*}
        \det_{\substack{1\le i \le n\\ 1\leq j\leq n-1}}\big(\eta_i(k+1/2) ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ p_+(j)\eta_i(k+1/2+j)+p_-(j)\eta_i(k+1/2-j)\big)\\=\sum_{\substack{(y_0,\dots,y_{ k}) \in\mathbb{Z}^{k + 1} \\ y_k \geq 0}}
        (-1)^{\binom{k+1}{2}
        +\sum_{j=0}^{k}
        (y_j+b_j)} \prod_{j=1}^{n-1}p_+(j) 
        \prod_{i=0}^{k}
        \prod_{\ell=0}^{\alpha_iy_i-1}
        \frac{p_-(K\ell+k+\alpha_i i+[y_i\geq 0])}{p_+(K\ell+k+\alpha_i i+[y_i\geq 0])}\\\times
         \det_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not=z(y_r)-1/2, r=0,\dots,k}}(\eta_i(k+1/2) ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ \eta_i(j+1/2)),
    \end{multline*}
    where $K=2k+1$ and $z(y_j)=\alpha_j(Ky_j+j+1/2)$ 
    with $\alpha_j=1$ if $y_j \geq 0$ and $-1$ otherwise, and $b_j=\vert\{i| z(y_i)> z(y_j)\textrm{ and }i>j\}\vert$.
    The sum is restricted by $\tfrac12\leq z(y_r)\leq k+n-\tfrac12$ for $r=0,\ldots,k$.

\label{lem: noodle-doodle expansion 2.1b}
    Let $\eta_1,\dots,\eta_n$ be functions on $\frac{1}{2}\mathbb{Z}$ with $\eta_i(a) = -\eta_i(-a)$. 
    Then
    \begin{multline*}
        \det_{1\le i,j \le n}\big({p_+(j)\eta_i(k+j-1/2)+p_-(j)\eta_i(k-j+1/2)}\big)\\=\sum_{(y_0,\dots,y_{ k-1}) \in\mathbb{Z}^{k}}
        (-1)^{\binom{k}{2}
        +\sum_{j=0}^{k-1}b_j} \prod_{j=1}^{n}p_+(j) 
        \prod_{i=0}^{k-1}
        \prod_{\ell=0}^{\alpha_iy_i-1}
        \frac{p_-(K\ell+k+\alpha_i i+[y_i\geq 0])}{p_+(K\ell+k+\alpha_i i+[y_i\geq 0])}\\\times
         \det_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not=z(y_r)-1/2, r=0,\dots,k-1}}({\eta_i(j+1/2)}),
    \end{multline*}
    where $K=2k$ and $z(y_j)=\alpha_j(Ky_j+j+1/2)$ 
    with $\alpha_j=1$ if $y_j \geq 0$ and $-1$ otherwise, and where we let $b_j=\vert\{i| z(y_i)> z(y_j)\textrm{ and }i>j\}\vert$.
    The sum is restricted by $\tfrac12\leq z(y_r)\leq k+n-\tfrac12$ for $r=0,\ldots,k-1$.

\label{lem: noodle-doodle expansion 2.1c}
    Let $\zeta_1,\dots,\zeta_n$ be functions on $\mathbb{Z}$ with $\zeta_i(a) =\zeta_i(-a)$. 
    Then
    \begin{multline*}
        \det_{\substack{1\le i \le n\\ 1\leq j\leq n-1}}\big(\zeta_i(k) ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ p_+(j)\zeta_i(k+j)+p_-(j)\zeta_i(k-j)\big)=\sum_{\substack{(y_0,\dots,y_{ k}) \in\mathbb{Z}^{k +1} \\ y_0,y_k \geq 0}}
        (-1)^{\binom{k+1}{2}
        +\sum_{j=0}^{k}
        (b_j-y_j)}\\\times\prod_{j=1}^{n-1}p_+(j) 
        \prod_{i=0}^{k}
        \prod_{\ell=0}^{\alpha_iy_i-1}
        \frac{p_-(K\ell+k+\alpha_i i)}{p_+(K\ell+k+\alpha_i i)}
         \det_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not=z(y_r), r=0,\dots,k}}(\zeta_i(k) ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ \zeta_i(j)),
    \end{multline*}
    where $K=2k$ and $z(y_j)=\alpha_j(Ky_j+j)$ 
    with $\alpha_j=1$ if $y_j \geq 0$ and $-1$ otherwise, and where we let  $b_j=\vert\{i| z(y_i)> z(y_j)\textrm{ and }i>j\}\vert$.
    The sum is restricted by $0\leq z(y_r)\leq k+n-1$ for $r=0,\ldots,k$.

\label{lem: noodle-doodle expansion 2.3a}
    Let $\eta_1,\dots,\eta_n$ be functions on $\mathbb{Z}$ with $\eta_i(a) =-\eta_i(-a)$. 
    Then
    \begin{multline*}
        \det_{\substack{1\le i \le n\\ 1\leq j\leq n-1}}\big(\eta_i(k+1) ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ p_+(j)\eta_i(k+1+j)+p_-(j)\eta_i(k+1-j)\big)
        \\=\sum_{\substack{(y_0,\dots,y_{k+1}) \in\mathbb{Z}^{k +2} \\ y_0,y_{k+1} \geq 0}}
        (-1)^{\binom{k+2}{2}
        +\sum_{j=0}^{k+1}
        (b_j-[y_j<0])}\prod_{j=1}^{n-1}p_+(j) 
        \prod_{i=0}^{k+1}
        \prod_{\ell=0}^{\alpha_iy_i-1}
        \frac{p_-(K\ell+k+1+\alpha_i i)}{p_+(K\ell+k+1+\alpha_i i)}
         \\\times\det_{\substack{1\le i\le n \\0 \le j\le k+n \\ j \not=z(y_r), r=0,\dots,k+1}}(\eta_i(k+1) ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ \eta_i(j)),
    \end{multline*}
    where $K=2k+2$ and $z(y_j)=\alpha_j(Ky_j+j)$ 
    with $\alpha_j=1$ if $y_j \geq 0$ and $-1$ otherwise, and where we let $b_j=\vert\{i| z(y_i)> z(y_j)\textrm{ and }i>j\}\vert$.
    The sum is restricted by $0\leq z(y_r)\leq k+n$ for $r=0,\ldots,k+1$.

\label{lem: noodle-doodle expansion 2.3b}
    Let $\eta_1,\dots,\eta_n$ be functions on $\mathbb{Z}$ with $\eta_i(a) = -\eta_i(-a)$. 
    Then
    \begin{multline*}
        \det_{1\le i,j \le n}\big({p_+(j)\eta_i(k+j)+p_-(j)\eta_i(k-j)}\big)=\sum_{\substack{(y_0,\dots,y_{ k}) \in\mathbb{Z}^{k + 1} \\y_0,y_k \geq 0}}
        (-1)^{\binom{k+1}{2}
        +\sum_{j=0}^{k}
        (b_j-[y_j<0])} \\
        \times \prod_{j=1}^np_+(j) 
        \prod_{i=0}^{k}
        \prod_{\ell=0}^{\alpha_iy_i-1}
        \frac{p_-(K\ell+k+\alpha_i i)}{p_+(K\ell+k+\alpha_i i)}
         \det_{\substack{1\le i\le n \\0 \le j\le k+n \\ j \not=z(y_r), r=0,\dots,k}}({\eta_i(j)}),
    \end{multline*}
    where $K=2k$ and $z(y_j)=\alpha_j(Ky_j+j)$ 
    with $\alpha_j=1$ if $y_j \geq 0$ and $-1$ otherwise, and where we let $b_j=\vert\{i| z(y_i)> z(y_j)\textrm{ and }i>j\}\vert$.
    The sum is restricted by $0\leq z(y_r)\leq k+n$ for $r=0,\ldots,k$.

\label{lem: noodle-doodle expansion 2.5a}
    Let $\eta_1,\dots,\eta_n$ be functions on $\mathbb{Z}$ with $\eta_i(a) = -\eta_i(-a)$. 
    Then
    \begin{multline*}
        \det_{1\le i,j \le n}\big({p_+(j)\eta_i(k+j)+p_-(j)\eta_i(k+1-j)}\big)\\=\sum_{\substack{(y_0,\dots,y_{ k}) \in\mathbb{Z}^{k+1}\\ y_0\geq 0}}
        (-1)^{\binom{k+1}{2}
        +\sum_{j=0}^{k}(y_j+b_j-[y_j<0])} \prod_{j=1}^{n}p_+(j) 
        \prod_{i=0}^{k}
        \prod_{\ell=0}^{\alpha_iy_i-1}
        \frac{p_-(K\ell+k+\alpha_i i+1)}{p_+(K\ell+k+\alpha_i i+1)}\\\times
         \det_{\substack{1\le i\le n \\0 \le j\le k+n \\ j \not=z(y_r), r=0,\dots,k}}({\eta_i(j)}),
    \end{multline*}
    where $K=2k+1$ and $z(y_j)=\alpha_j(Ky_j+j)$ 
    with $\alpha_j=1$ if $y_j \geq 0$ and $-1$ otherwise, and where we let $b_j=\vert\{i| z(y_i)> z(y_j)\textrm{ and }i>j\}\vert$.
    The sum is restricted by $0\leq z(y_r)\leq k+n$ for $r=0,\ldots,k$.

\label{lem:flip}
    Given two partitions $\lambda \subseteq (k^n)$ and $\mu \subseteq (n^k)$, the following are equivalent:
    \begin{enumerate}
        \item $(\lambda+\rho_n)\sqcup(\mu + \rho_k) = \rho_{k+n}$,
        \item $[\lambda] \sqcup \mathrm{flip}_{k^n}\mu = (k^n)$,
        \item $\lambda = (\mu^{\square n^k})'$,
        \item $m_{k-i}(\lambda) = \mu_i - \mu_{i+1}$ for all $i=0,\ldots,k-1$, where $\mu_0 = n$,
        \item $m_{k-i}(\lambda) = (\mu + \rho_k)_i - (\mu+\rho_k)_{i+1} - 1$ for all $i=0,\ldots,k-1$, where $(\mu+\rho_k)_0 = n+k$.
    \end{enumerate}

Setting $s_1=0$ and $s_2=-1$ in the expression of Lemma~\ref{magical manipulation} we get
\begin{multline*}
    P^{\mathrm{B}_n}_{(k^n)}(X;t,0)= 
        \frac{\sqrt{t}^{\binom{n}{2}}}{2}
        \prod_{i=1}^nx_i^{n-1}\prod_{1\leq i<j\leq n}\frac{1}{(1-x_ix_j)(x_i-x_j)}\\\times\det_{1\le i,j\le n}\left(\frac{1}{1-x_i}\left((\sqrt{t})^{j-1}
        x_i^{j-1-k} +
        (\sqrt{t})^{-j+1}x_i^{-j+1-k}\right)\right.\\
        \left.-\frac{x_i}{1-x_i}\left((\sqrt{t})^{j-1}
        x_i^{-j+1+k}+(\sqrt{t})^{-j+1}x_i^{j-1+k}\right)\right)\\
        = \frac{\sqrt{t}^{\binom{n}{2}}}{2}\prod_{i=1}^n \frac{x_i^{n-1}}{x_i-1}
        \prod_{1\leq i<j\leq n}\frac{1}{(1-x_ix_j)(x_i-x_j)} 
        \\\times\det_{1\le i,j\le n} \left(
        (\sqrt{t})^{-j+1}\left(
        x_i^{k+(j-1)+1}
        - \bar{x}_i^{k+(j-1)}\right) +
        (\sqrt{t})^{j-1}\left(
        x_i^{k-(j-1)+1}
        - \bar{x}_i^{k-(j-1)}\right)
        \right).
\end{multline*}
We identify in the prefactor the Weyl denominator of type \ref{eq: Denom type B} up to a factor of $\prod_{i=1}^n x_i^{-1/2}$, which we can distribute over the determinant, and a sign $(-1)^{\binom{n}{2}}$ to obtain
\begin{multline*}
            \frac{(-\sqrt{t})^{\binom{n}{2}}}{2}\\\times 
        \frac{\det\limits_{1\leq i,j\leq n}\left(
        (\sqrt{t})^{-j+1}\left(
        x_i^{k+(j-1)+1/2}
        - \bar{x}_i^{k+(j-1)+1/2}\right)
        +
        (\sqrt{t})^{j-1}\left(
        x_i^{k-(j-1)+1/2}
        - \bar{x}_i^{k-(j-1)+1/2}\right)
        \right)}{\det\limits_{1\leq i,j\leq n}\left(x_i^{n-j+1/2}-\bar{x}_i^{n-j+1/2}\right)}\,.
\end{multline*}
Using the shorthand $\eta_j(m)$ for the expression $x_j^m-\bar{x}_j^m$, we observe that in the first column of the determinant, the $i$-th entry is $2\eta_i(k+1/2)$. We pull the $2$ out of the first column by linearity, and cancel it with the $1/2$ in the prefactor above to rewrite our expression as
\begin{multline*}
    P^{\mathrm{B}_n}_{(k^n)}(X;t,0)\\=(-\sqrt{t})^{\binom{n}{2}}
\frac{\det\limits_{\substack{1\le i\le n \\1\le j < n}}\left(

\eta_i(k+1/2)
 ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ 
(\sqrt{t})^{-j}\eta_i(k+j+1/2) +
(\sqrt{t})^{j}\eta_i(k-j+1/2)
\right)}{
\det\limits_{1\le i,j\le n }\left(\eta_i(n-j+1/2)\right)
}\,.
\end{multline*}
We invoke Lemma~\ref{lem: noodle-doodle expansion 2.1a} with $\eta_j(a)=x_j^a-\bar{x}_j^a$, $p_\pm(j) = (\sqrt{t})^{\mp j}$ and $K=2k+1$ to obtain
\begin{multline*}
    \det\limits_{\substack{1\le i\le n \\1\le j < n}}\left(

\eta_i(k+1/2)
 ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ 
(\sqrt{t})^{-j}\eta_i(k+j+1/2) +
(\sqrt{t})^{j}\eta_i(k-j+1/2)
\right)\\= \sum_{\substack{(y_0,\ldots,y_{k})\in\mathbb{Z}^{k+1}\\y_k\geq 0}}
(-1)^{|y|+\operatorname{inv}(\vec z_{0,k})}
t^{- \frac{1}{2}
 \binom{n}{2}
  + \sum_{i=0}^k \left( \frac{1}{2}Ky_i^2 + y_i (i+ \frac{1}{2}) \right)}\\\times\det_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not=z(y_r)-1/2, r=0,\dots,k}}(\eta_i(k+1/2) ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ \eta_i(j+1/2)),
\end{multline*}
where $z(y_j)=\alpha_j(Ky_j+j+1/2)$ and we denote $\vec{z}_{0,k}\coloneqq(z(y_0), z(y_1), \ldots, z(y_k))$. This is because $$(-1)^{\binom{k+1}{2}
        +\sum_{j=0}^{k}
        (y_j+b_j)}=(-1)^{|y|+\operatorname{inv}(\vec z_{0,k})},$$
as $ \operatorname{inv}(\vec z_{0,k})= |\{(i,j)\mid i>j,~ z(y_i) < z(y_j)\}|=\binom{k+1}{2} - \sum_{j=0}^{k} b_j$
is the number of inversions of $\vec z_{0,k}$ and we know that
\begin{equation*}
    \prod_{j=1}^{n-1}p_+(j) 
        \prod_{i=0}^{k}
        \prod_{\ell=0}^{\alpha_iy_i-1}
        \frac{p_-(K\ell+k+\alpha_i i+[y_i\geq 0])}{p_+(K\ell+k+\alpha_i i+[y_i\geq 0])}\\=t^{- \frac{1}{2}
 \binom{n}{2}
  + \sum_{i=0}^k \left( \frac{1}{2}Ky_i^2 + y_i (i+ \frac{1}{2}) \right)},
\end{equation*}
by the following simple calculation:
\begin{multline*}
-\sum_{j=1}^{n-1}
\frac{j}{2} +
\sum_{i=0}^k
\sum_{\ell=0}^{|y_i|-1}
\left(K\ell + k + \alpha_ii + [y_i\ge0] \right)
\\ =
- \frac{1}{2}\binom{n}{2} + 
 \sum_{i=0}^k
 \left(K\binom{|y_i|}{2} + y_ii + |y_i|\Big( k+[y_i\ge0]\Big)\right)
\\
=  - \frac{1}{2}
 \binom{n}{2}
  + \sum_{i=0}^k \left( \frac{1}{2}Ky_i^2 + y_i (i+{\textstyle \frac{1}{2}}) \right),
\end{multline*}
where the last equality holds summand-by-summand by distinguishing cases on the sign of~$y_i$. Therefore, inserting into our expression from before we have
\begin{multline*}
     P^{\mathrm{B}_n}_{(k^n)}(X;t,0) 
 =     
 \sum_{\substack{(y_0,\ldots,y_{k})\in\mathbb{Z}^{k+1}\\y_k\geq 0}}
(-1)^{\binom{n}{2}+|y|+\operatorname{inv}(\vec z_{0,k})}
t^{\sum_{i=0}^{k} \left( \frac{1}{2}Ky_i^2 + y_i (i+{\frac{1}{2}}) \right)}\\\times
\frac{\det\limits_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not=z(y_r)-1/2, r=0,\dots,k}}(\eta_i(k+1/2) ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ \eta_i(j+1/2))}{\det\limits_{1 \le i,j \le n}(\eta_i(n-j+1/2))}\,.
\end{multline*}


Now consider the determinant
$$\det_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not=z(y_r)-1/2, r=0,\dots,k}}(\eta_i(k+1/2) ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ \eta_i(j+1/2)),$$
in the numerator. The first column is $\eta_i(k+1/2)$. However, if $z(y_i)\ne k+1/2$ for all $i$, then there is a second column of the same form, and hence the determinant vanishes. Note that $z(y_i) = k+1/2$ if and only if $i=k$ and $y_k\in\{0,-1\}$. Since $y_k\ge0$, we have only one option and may thus assume $y_k=0$ from now on. Note that then $$ \operatorname{inv} (\vec z_{0,k})=\operatorname{inv}((z(y_0),\dots,z(y_{k-1}),k+1/2)=\operatorname{inv}(\vec z_{0,k-1})+|\{j\in[0,k-1]\mid k+1/2<z(y_j)\}|.$$
We reorder the columns of the determinant to be in increasing order with respect to the arguments of $\eta_i$. The only misplaced column is the first. This introduces a sign of $$(-1)^{k-|\{j\in[0,k-1]\mid z(y_j)< k+1/2\}|}=(-1)^{|\{j\in[0,k-1]\mid k+1/2<z(y_j)\}|},$$
as there are $k-|\{j\in[0,k-1]\mid z(y_j)< k+1/2\}|$ many columns after the first column of our matrix where the argument of $\eta_i$ is smaller than $k+1/2$. Thus, we have arrived at
\begin{multline*}
     P^{\mathrm{B}_n}_{(k^n)}(X;t,0) 
 =     
 \sum_{(y_0,\ldots,y_{k-1})\in\mathbb{Z}^{k}}
(-1)^{\binom{n}{2}+|y|+\operatorname{inv}(\vec z_{0,k-1})}
t^{\sum_{i=0}^{k-1} \left( \frac{1}{2}Ky_i^2 + y_i (i+{\frac{1}{2}}) \right)}\\\times
\frac{\det\limits_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not=z(y_r)-1/2, r=0,\dots,k-1}}(\eta_i(j+1/2))}{\det\limits_{1 \le i,j \le n}(\eta_i(n-j+1/2))}\,.
\end{multline*}


To be able to use the Weyl character formula of type $\mathrm{B}_n$ \eqref{eq: Weyl character formula type B} and Corollary~\ref{cor:useful.complementary}, we define a vector $\nu\coloneqq (\nu_1,\dots, \nu_k)$ by
\[
\nu_i := z(y_{i-1})-\frac{1}{2}=\alpha_{i-1}(Ky_{i-1}+i-1+1/2)-1/2 = |Ky_{i-1}+i| - [y_{i-1}\ge0]
\]
for $i=1,\ldots,k$
and use $\operatorname{inv}(\vec z_{0,k-1}) = \operatorname{inv}(\nu),$
to reindex the sum by simultaneously setting $y_i\rightarrow y_{i+1}$ for $i=0,\dots k-1$ and write it as a sum over tuples $(y_1,\ldots,y_k)\in \mathbb{Z}^k$, to obtain
\[
 P^{\mathrm{B}_n}_{(k^n)}(X;t,0) 
 =     
 \sum_{(y_1,\ldots,y_k)\in\mathbb{Z}^{k}}
(-1)^{\binom{n}{2}+|y|+\operatorname{inv}(\nu)}
t^{\sum_{i=1}^k \left( \frac{1}{2}Ky_i^2 + y_i (i-{\frac{1}{2}}) \right)}
\frac{\det\limits_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not={\nu}_r, r=1,\dots,k}}(\eta_i(j+1/2))}{\det\limits_{1 \le i,j \le n}(\eta_i(n-j+1/2))}\,.
\]

By the Weyl character formula of type $\mathrm{B}_n$ \eqref{eq: Weyl character formula type B} and Corollary~\ref{cor:useful.complementary}, we know that
\[
\frac{\det\limits_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not={\nu}_r, r=1,\dots,k}}(\eta_i(j+1/2))}{\det\limits_{1 \le i,j \le n}(\eta_i(n-j+1/2))}= 
(-1)^{\binom{n}{2}}so_{\lambda(\nu)}(X).
\]
Note that the condition for the matrix in the numerator to be a square matrix is precisely the condition that the $y_a$'s corresponding $\nu_a$'s are inside $\{0,\dots,n+k-1\}$ and are all different. Plugging this into our expression for $P^{\mathrm{B}_n}_{(k^n)}(X;t,0)$ from above yields
\[
    P^{\mathrm{B}_n}_{(k^n)}(X;t,0)= 
 \sum_{(y_1,\ldots,y_k)\in\mathbb{Z}^{k}}
 (-1)^{|y|+\operatorname{inv}(\nu)}
t^{\sum_{i=1}^k \left( \frac{1}{2}Ky_i^2 + y_i (i-{\frac{1}{2}}) \right)}so_{\lambda(\nu)}(X),
\]
where we sum over all $y\in\mathbb{Z}^k$ such that the corresponding $\nu_a$'s are inside $\{0,\dots,n+k-1\}$ and are all different, as claimed.

Let $\nu_a = |Ky_a + a| - [y_a\ge0]$ as in~\eqref{thm-type-b-0-char}. 
Unravelling the Definition~\ref{de:lambda(nu)}, we have
\begin{multline*}
\lambda(\nu)'_i = (\mathrm{sort}(\nu) - \rho_k)^{\square n^k}_i = 
n - (\mathrm{sort}(\nu) - \rho_k)_{k+1-i} =
n - \mathrm{sort}(\nu)_{k+1-i} + i -1\\
= n - |Ky_{\sigma(i)} + {\sigma(i)}| + [y_{\sigma(i)}\ge0] + i-1\,,
\end{multline*}
where $\sigma$ is the permutation that sorts $\nu$ into increasing order.

We apply the dual Jacobi--Trudi identity of type $\mathrm{B}_n$ \eqref{eq: dual JT type B} to the formula~\ref{thm-type-b-0-char} of Theorem \ref{thm-b-char} to get
\[
P_{(k^n)}^{\mathrm{B}_n}(X;t,0)=\sum_{y \in \mathbb{Z}^k}
(-1)^{|y|+\operatorname{inv}(\nu)}
t^{\sum_{j=1}^k \left( \frac{1}{2}K y_j^2 + (j-\frac{1}{2})y_j \right)}
\det_{1\leq i,j\leq k}(\dot{e}_{\lambda(\nu)'_i-i+j}
+ 
\dot{e}_{\lambda(\nu)'_i-i-j+1}).
\]
By the assumption in Theorem \ref{thm-b-char}, the sum ranges over all vectors $y\in\mathbb{Z}^k$ such that $\nu_1,\dots,\nu_k\in[0,n+k-1]$ are all different elements. By Lemma \ref{lem: handling the summation range} the determinant on the right hand side of this sum vanishes outside of this range of summation, hence we can extend the sum, to a sum over all $y\in\mathbb{Z}^k$. 

Plugging in the expression for $\lambda(\nu)'_i$ that we got before, the determinant is given by
\[
\det_{1\leq i,j\leq k}\left(
\dot{e}_{
n - |Ky_{\sigma(i)} + {\sigma(i)}| + [y_{\sigma(i)}\ge0]-1 + j
} +
\dot{e}_{
n - |Ky_{\sigma(i)} + {\sigma(i)}| + [y_{\sigma(i)}\ge0] - j 
}\right).
\]
Now we rearrange the rows of the matrix by the permutation $\sigma^{-1}$. This cancels the factor $\operatorname{sgn}(\sigma) = (-1)^{\mathrm{inv}(\nu)}$, since $\sigma$ is the permutation that sorts $\nu$ in increasing order and hence the sign is given by the number of inversions of $\nu$.  
The determinant becomes
\[
\det_{1\leq i,j\leq k}\left(
\dot{e}_{
n - |Ky_{i} + {i}| + [y_{i}\ge0] -1+ j
} +
\dot{e}_{
n - |Ky_{i} + {i}| + [y_{i}\ge0] - j 
}\right).
\]
We distinguish cases according to the sign of $y_i$ and fix some $1\leq j\leq k$.
If $y_i$ is non-negative, we use the formula
$\dot{e}_{n+r} = \dot{e}_{n-r}$ to get 
\begin{multline*}
\dot{e}_{
n - |Ky_{i} + {i}| + [y_{i}\ge0] -1+ j
} +
\dot{e}_{
n - |Ky_{i} + {i}| + [y_{i}\ge0] - j 
}\\=
\dot{e}_{
n - Ky_{i} - i + j 
} +
\dot{e}_{
n - Ky_{i} - i - j + 1
}=
\dot{e}_{
n + Ky_{i} + i - j 
} +
\dot{e}_{
n + Ky_{i} + i + j - 1
}.
\end{multline*}
If $y_i$ is negative, we immediately get that
\begin{equation*}
   \dot{e}_{
n - |Ky_{i} + {i}| + [y_{i}\ge0] -1+ j
} +
\dot{e}_{
n - |Ky_{i} + {i}| + [y_{i}\ge0] - j 
}=
\dot{e}_{
n + Ky_{i} + i + j-1
} +
\dot{e}_{
n + Ky_{i} + i - j}.
\end{equation*}
Replacing $y_i$ by $-y_i$ and transposing our matrix, we arrive at
    \[
\sum_{y \in \mathbb{Z}^k}
(-1)^{\sum_{j=1}^k y_j}
t^{\sum_{j=1}^k \left( \frac{1}{2} K y_j^2 - (j-\frac{1}{2})y_j \right)}
\det_{1 \le i,j \le k}
\left(
\dot{e}_{\,n-i+j-K y_j}
+
\dot{e}_{\,n+i+j- Ky_j-1}
\right).\]
By Lemma \ref{lem: handling the summation range}, the support of this sum is finite, so extending the sum to a finite $S_k$ invariant subset containing the support, by Lemma~\ref{lem:powery}, we get that this is equal to the right-hand side of~\eqref{thm-b-0}.

We set $s_1=-\sqrt{t}$ and $s_2=-1$ in the expression of Lemma~\ref{magical manipulation} to obtain
\begin{multline*}
    P_{(k^n)}^{\mathrm{B}_n}(X;t,-t^{1/2})= \frac{\sqrt{t}^{\binom{n}{2}}}{2}
    \prod_{i=1}^nx_i^{n-1}\prod_{1\leq i<j\leq n}\frac{1}{(1-x_ix_j)(x_i-x_j)}\\\times\det_{1\le i,j\le n}\left(\frac{(1+\sqrt{t}x_i)}{1-x_i}
    \left((\sqrt{t})^{j-1}x_i^{j-1-k}+
    (\sqrt{t})^{-j+1}x_i^{-j+1-k}\right)\right.\\\left.-\frac{(\sqrt{t}+x_i)}{1-x_i}
    \left((\sqrt{t})^{j-1}x_i^{-j+1+k}
    +(\sqrt{t})^{-j+1}x_i^{j-1+k}\right)\right)\\=
    \frac{\sqrt{t}^{\binom{n}{2}}}{2}
    \prod_{i=1}^n\frac{x_i^{n-1}}{x_i-1}\prod_{1\leq i<j\leq n}\frac{1}{(1-x_ix_j)(x_i-x_j)}\\\times\det_{1\le i,j\le n}\left(-(1+\sqrt{t}x_i)
    \left((\sqrt{t})^{j-1}x_i^{j-1-k}+
    (\sqrt{t})^{-j+1}x_i^{-j+1-k}\right)\right.\\\left.+(\sqrt{t}+x_i)
    \left((\sqrt{t})^{j-1}x_i^{-j+1+k}
    +(\sqrt{t})^{-j+1}x_i^{j-1+k}\right)\right).
\end{multline*}
Similarly as in the proof of \eqref{thm-type-b-0-char}, we identity the Weyl denominator of type \ref{eq: Denom type B} up to a factor of $\prod_{i=1}^nx_i^{-1/2}$, which we distribute over the determinant, and a sign $(-1)^{\binom{n}{2}}$ to obtain
\begin{multline*}
    \frac{(-\sqrt{t})^{\binom{n}{2}}}{2}
    \det_{1\le i,j\le n}\left(-(1+\sqrt{t}x_i)\left((\sqrt{t})^{j-1}x_i^{j-3/2-k}+(\sqrt{t})^{-j+1}x_i^{-j+1/2-k}\right)\right.\\\left.+
  {( \sqrt{t}+x_i)}
  \left((\sqrt{t})^{j-1}x_i^{-j+1/2+k}+(\sqrt{t})^{-j+1}x_i^{j-3/2+k}\right)\right)/\det_{1\leq i,j\leq n}\left(x_i^{n-j+1/2}-\bar{x}_i^{n-j+1/2}\right)
\end{multline*}
Using our shorthand notation $\eta_j(m)$ for the expression $x_j^m-\bar{x}_j^m$ again, we can rewrite this expression as
\begin{multline*}
    \frac{(-\sqrt{t})^{\binom{n}{2}}}{2}\det\limits_{1\leq i,j\leq n}\left((\sqrt{t})^{j-1} \eta_i(k-j+3/2)
 +(\sqrt{t})^{j} \eta_i(k-j+1/2) \right.\\\left.
 +(\sqrt{t})^{-j+1} \eta_i(k+j-1/2) +(\sqrt{t})^{-j+2}\eta_i(k+j-3/2)\right)/\det\limits_{1\leq i,j\leq n}(\eta_i(n-j+1/2)),
\end{multline*}
Now observe that the determinant in the numerator equals the following determinant, where we factored out the $2$ from the first column, since the first matrix can be obtained from the latter by applying elementary column operations $C_j \rightarrow C_j+C_{j-1}$ for $j=n,\dots, 2$, 
\begin{multline*}
2 \det\limits_{1\leq i,j\leq n}\left((\sqrt{t})^{-j+1} \eta_i(k+j-1/2)
+(\sqrt{t})^j \eta_i(k-j+1/2)\right)
\\ = 2(\sqrt{t})^{\frac{n}{2}}\cdot
\det\limits_{1\leq i,j\leq n}\left((\sqrt{t})^{-(j-\frac{1}{2})} \eta_i(k+j-1/2)
+
(\sqrt{t})^{j-\frac{1}{2}} \eta_i(k-j+1/2)\right)\,.
\end{multline*}
So our expression is equal to
\begin{multline*}
    P_{(k^n)}^{\mathrm{B}_n}(X;t,-t^{1/2})\\=(-1)^{\binom{n}{2}}(\sqrt{t})^{\binom{n}{2}+\frac{n}{2}}\frac{\det\limits_{1\leq i,j\leq n}\left((\sqrt{t})^{-(j-\frac{1}{2})} \eta_i(k+j-1/2)
+
(\sqrt{t})^{j-\frac{1}{2}} \eta_i(k-j+1/2)\right)}{\det\limits_{1\leq i,j\leq n}(\eta_i(n-j+1/2))}.
\end{multline*}
We use Lemma~\ref{lem: noodle-doodle expansion 2.1b} with $\eta_j(a)=x_j^a-\bar{x}_j^a$, $p_{\pm}(j) = (\sqrt{t})^{\mp(j-\frac{1}{2})}$ and $K=2k$ to obtain
\begin{multline*}
    \det\limits_{1\leq i,j\leq n}\left((\sqrt{t})^{-(j-\frac{1}{2})} \eta_i(k+j-1/2)
+
(\sqrt{t})^{j-\frac{1}{2}} \eta_i(k-j+1/2)\right)\\= \sum_{(y_0,\dots,y_{ k-1}) \in\mathbb{Z}^{k}}
        (-1)^{\operatorname{inv}(\vec z_{0,k-1})}t^{-\frac{n^2}{4} + \sum_{i=0}^{k-1} \left( \frac{1}{2}Ky_i^2 + (i+\frac{1}{2})y_i \right)}\\\times
         \det_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not=z(y_r)-1/2, r=0,\dots,k-1}}({\eta_i(j+1/2)}),
\end{multline*}
where $z(y_j)=\alpha_j(Ky_j+j+1/2)$ and we denote $\vec z_{0,k-1}\coloneqq(z(y_0),\dots,z(y_{k-1}))$. This is because as in the proof of \eqref{thm-type-b-0-char}, we have $\binom{k}{2} - \sum_{j=0}^{k-1} b_j = \operatorname{inv}(\vec z_{0,k-1})$, and furthermore we get that
\begin{equation*}
    \prod_{j=1}^{n}p_+(j) 
        \prod_{i=0}^{k-1}
        \prod_{\ell=0}^{\alpha_iy_i-1}
        \frac{p_-(K\ell+k+\alpha_i i+[y_i\geq 0])}{p_+(K\ell+k+\alpha_i i+[y_i\geq 0])}=t^{-\frac{n^2}{4} + \sum_{i=0}^{k-1} \left( \frac{1}{2}Ky_i^2 + (i+\frac{1}{2})y_i \right)},
\end{equation*}
from the following simple calculation:
\begin{multline*}
-\frac{1}{2}\sum_{j=1}^n \left(j-\frac{1}{2}\right) +\sum_{i=0}^{k-1}
\sum_{\ell=0}^{|y_i|-1}
\left(K\ell+k + \alpha_ii + [y_i\ge0]-\frac{1}{2}\right)
\\
= -\frac{1}{2}\left(\binom{n+1}{2} - \frac{n}{2}\right) + \sum_{i=0}^{k-1}
\left( K\binom{|y_i|}{2} + |y_i|\left(k +\alpha_i i + [y_i\ge0]-\frac{1}{2}\right) \right)
\\
= 
-\frac{n^2}{4} + \sum_{i=0}^{k-1} \left( \frac{1}{2}Ky_i^2 + (i+{\textstyle\frac{1}{2}})y_i \right),  
\end{multline*}
where the last equality follows summand-by-summand by a case distinction on the sign of $y_i$. Inserting this into our expression from before we obtain
\begin{multline*}
    P_{(k^n)}^{\mathrm{B}_n}(X;t,-t^{1/2}) \\=
\sum_{(y_0, \ldots, y_{k-1})\in\mathbb{Z}^k}
(-1)^{\binom{n}{2}+\operatorname{inv}(\vec z_{0,k-1})}
t^{\sum_{i=0}^{k-1} \left( \frac{1}{2}Ky_i^2 + (i+\frac{1}{2})y_i \right)}
\frac{\det\limits_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not=z(y_r)-1/2, r=0,\dots,k-1}}(\eta_i(j+1/2))}{\det\limits_{1 \le i,j \le n}(\eta_i(n-j+1/2))}   \,.
\end{multline*}

To able to use the Weyl character formula of type $\mathrm{B}_n$ \eqref{eq: Weyl character formula type B} and Corollary~\ref{cor:useful.complementary}, we define a vector $\nu\coloneqq(\nu_1,\dots,\nu_k)$ by
$$\nu_i = z(y_{i-1}) -\frac{1}{2} = \alpha_{i-1}\Big(Ky_{i-1} + i - 1 + \frac{1}{2}\Big)-\frac{1}{2}
= |Ky_{i-1} + i| - [y_{i-1}\ge0],$$
for $i=1,\ldots,k$
and use $\operatorname{inv}(\vec z_{0,k-1}) = \operatorname{inv}(\nu)$
and then simultaneously set $y_i\rightarrow y_{i+1}$ for $i=0,\dots k-1$ to write our expression as
\[
P_{(k^n)}^{\mathrm{B}_n}(X;t,-t^{1/2})=
\sum_{(y_1, \ldots, y_k)\in\mathbb{Z}^k}
(-1)^{\binom{n}{2}+\operatorname{inv}(\nu)}
t^{\sum_{i=1}^{k} \left( \frac{1}{2}Ky_i^2 + (i-\frac{1}{2})y_i \right)}
\frac{\det\limits_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not=\nu_r, r=1,\dots,k}}(\eta_i(j+1/2))}{\det\limits_{1\le i,j\le n}(\eta_i(n-j+1/2))}.
\]

By the Weyl character formula of type $\mathrm{B}_n$ \eqref{eq: Weyl character formula type B} and Corollary~\ref{cor:useful.complementary} we find that
\[
(-1)^{\binom{n}{2}}
\frac{\det\limits_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not=\nu_r, r=1,\dots,k}}(\eta_i(j+1/2))}{\det\limits_{1\le i,j\le n}(\eta_i(n-j+1/2))}
= so_{\lambda(\nu)}(X).
\]
Note that the condition for the matrix in the numerator to be a square matrix is precisely the condition that the $y_a$'s corresponding to the $\nu_a$'s are inside $\{0,\dots,n+k-1\}$ and are all different.
Plugging this into our expression from above we obtain
\[
P_{(k^n)}^{\mathrm{B}_n}(X;t,-t^{1/2})=
\sum_{(y_1, \ldots, y_k)\in\mathbb{Z}^k}
(-1)^{\operatorname{inv}(\nu)}
t^{\sum_{i=1}^{k} \left( \frac{1}{2}Ky_i^2 + (i-\frac{1}{2})y_i \right)}
so_{\lambda(\nu)}(X),
\]
where we sum over all $y\in\mathbb{Z}^k$ such that the corresponding $\nu_a$'s are inside $\{0,\dots,n+k-1\}$ and are all different, as claimed.

Let $\nu_a = |Ky_a + a | - [y_a\ge0]$ as in~\eqref{thm-type-b-t-char}. 
Unravelling the Definition~\ref{de:lambda(nu)}, we have
\begin{multline*}
\lambda(\nu)'_i = (\mathrm{sort}(\nu) - \rho_k)^{\square n^k}_i = 
n - (\mathrm{sort}(\nu) - \rho_k)_{k+1-i} =
n - \mathrm{sort}(\nu)_{k+1-i} + i -1\\
= n - |Ky_{\sigma(i)} + {\sigma(i)}| + [y_{\sigma(i)}\ge0] + i-1\,,
\end{multline*}
where $\sigma$ is the permutation that sorts $\nu$ into increasing order.

We apply the dual Jacobi--Trudi identity of type $\mathrm{B}_n$ \eqref{eq: dual JT type B} to the formula \ref{thm-type-b-t-char} to get
\[
P_{(k^n)}^{\mathrm{B}_n}(X;t,-t^{1/2})=\sum_{(y_1, \ldots, y_k)\in\mathbb{Z}^k}
(-1)^{\mathrm{inv}(\nu)}t^{\sum_{j=1}^k \left( \frac{1}{2}Ky_j^2 + (j -
\frac{1}{2})y_j \right)
}
\det_{1\leq i,j\leq k}(\dot{e}_{\lambda(\nu)'_i-i+j}
+ 
\dot{e}_{\lambda(\nu)'_i-i-j+1}).
\]
By the assumption in Theorem \ref{thm-b-char}, the sum ranges over all vectors $y\in\mathbb{Z}^k$ such that $\nu_1,\dots,\nu_k\in[0,n+k-1]$ are all different elements. By Lemma \ref{lem: handling the summation range} the determinant on the right hand side of this sum vanishes outside of this range of summation, hence we can extend the sum, to a sum over all $y\in\mathbb{Z}^k$. 

Plugging in the expression for $\lambda(\nu)'_i$ that we got before, this determinant is
\[
\det_{1\leq i,j\leq k}\left(
\dot{e}_{
n - |Ky_{\sigma(i)} + {\sigma(i)} | + [y_{\sigma(i)}\ge0]-1 + j
} +
\dot{e}_{
n - |Ky_{\sigma(i)} + {\sigma(i)}| + [y_{\sigma(i)}\ge0] - j 
}\right).
\]
Now we rearrange the rows of the matrix by the permutation $\sigma^{-1}$. This cancels the factor $\operatorname{sgn}(\sigma) = (-1)^{\mathrm{inv}(\nu)}$, as $\sigma$ is the permutation that sorts $\nu$ in increasing order, hence the sign is given by the number of inversions of $\nu$. The matrix becomes
\[
\det_{1\leq i,j\leq k}\left(
\dot{e}_{
n - |Ky_{i} + {i}| + [y_{i}\ge0] -1+ j
} +
\dot{e}_{
n - |Ky_{i} + {i}| + [y_{i}\ge0] - j 
}\right).
\]
We distinguish cases according to the sign of $y_i$ and fix some $1\leq j\leq k$.
If $y_i$ is non-negative, we use the formula
$\dot{e}_{n+r} = \dot{e}_{n-r}$ to get 
\begin{multline*}
\dot{e}_{
n - |Ky_{i} + {i}| + [y_{i}\ge0] -1+ j
} +
\dot{e}_{
n - |Ky_{i} + {i}| + [y_{i}\ge0] - j 
}\\=\dot{e}_{
n - Ky_{i} - i + j 
} +
\dot{e}_{
n - Ky_{i} - i - j + 1
}=\dot{e}_{
n + Ky_{i} + i - j 
} +
\dot{e}_{
n + Ky_{i} + i + j - 1
}
\end{multline*}
If $y_i$ is negative, we immediately have that
\begin{equation*}
\dot{e}_{
n - |Ky_{i} + {i}| + [y_{i}\ge0] -1+ j
} +
\dot{e}_{
n - |Ky_{i} + {i}| + [y_{i}\ge0] - j 
}=\dot{e}_{
n + Ky_{i} + i + j-1
} +
\dot{e}_{
n + Ky_{i} + i - j \,.
}
\end{equation*}
Replacing $y_i$ by $-y_i$ and transposing our matrix,
we have arrived at
    \[\sum_{(y_1, \ldots, y_k)\in\mathbb{Z}^k}
t^{\sum_{j=1}^k \left( \frac{1}{2} K y_j^2 - (j-\frac{1}{2})y_j \right)}
\det_{1 \le i,j \le k}
\left(
\dot{e}_{\,n-i+j-K y_j}
+
\dot{e}_{\,n+i+j-Ky_j-1}
\right),\]
where we set $K=2k$. By Lemma \ref{lem: handling the summation range}, the support of this sum is finite, so extending the sum to a finite $S_k$ invariant subset containing the support, by Lemma~\ref{lem:powery}, we get that this is equal to the right-hand side of~\eqref{thm-type-b-t}.

Set $s_1=1$ and $s_2=-1$ in the expression of Lemma~\ref{magical manipulation} to get
    \begin{multline*}
    P_{(k^n)}^{\mathrm{B}_n}(X;t,1)= \frac{\sqrt{t}^{\binom{n}{2}}}{2}
    \prod_{i=1}^nx_i^{n-1}\prod_{1\leq i<j\leq n}\frac{1}{(1-x_ix_j)(x_i-x_j)}\\\times\det_{1\le i,j\le n}\left(
    (\sqrt{t})^{j-1}\left(x_i^{j-1-k}+x_i^{-j+1+k}\right)+
    (\sqrt{t})^{-j+1}\left(x_i^{-j+1-k}+x_i^{j-1+k}\right)\right).
\end{multline*}
We identify the Weyl denominator of type \ref{eq: Denom type D} up to a sign $(-1)^{\binom{n}{2}}$ to write this as
\begin{multline*}
    (-\sqrt{t})^{\binom{n}{2}}\det_{1\le i,j\le n}\left(
    (\sqrt{t})^{j-1}\left(x_i^{j-1-k}+x_i^{-j+1+k}\right)+
    (\sqrt{t})^{-j+1}\left(x_i^{-j+1-k}+x_i^{j-1+k}\right)\right)\\\times 1/\det_{1\leq i,j\leq n}\left(x_i^{n-j}+\bar{x}^{n-j}\right).
\end{multline*}
Using the shorthand notation $\zeta_i(m)$ for the expression $x_i^{m} + \bar{x}_i^{m}$, we observe that the first column of our matrix in the numerator is given by $2\zeta_i(k)$. Factoring out this $2$ by linearity, we can rewrite our expression as
\begin{equation*}
    P_{(k^n)}^{\mathrm{B}_n}(X;t,1)=2(-\sqrt{t})^{\binom{n}{2}}
  \frac{
  \det\limits_{\substack{1 \le i \le n\\ 1 \le j < n}}\left(
  \zeta_i(k)
   ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ 
  (\sqrt{t})^{j}\zeta_i(k-j) +(\sqrt{t})^{-j}\zeta_i(k+j)

  \right)
  }{\det\limits_{1 \le i,j \le n}(\zeta_i(n-j))}.
\end{equation*}

We use Lemma~\ref{lem: noodle-doodle expansion 2.1c} with $\zeta_i(a)=x_i^{a} + \bar{x}_i^{a}$, $p_{\pm}(j) = (\sqrt{t})^{\mp j}$ and $K=2k$ to obtain 
\begin{multline*}
    \det\limits_{\substack{1 \le i \le n\\ 1 \le j < n}}\left(
  \zeta_i(k)
   ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ 
  (\sqrt{t})^{j}\zeta_i(k-j) +(\sqrt{t})^{-j}\zeta_i(k+j)

  \right)\\=\sum_{\substack{(y_0,\dots,y_{ k}) \in\mathbb{Z}^{k +1} \\ y_0,y_k \geq 0}}
        (-1)^{|y|+\operatorname{inv}(\vec z_{0,k})} t^{-\frac{1}{2}\binom{n}{2} +\sum_{i=0}^{k} \left( \frac{1}{2}Ky_i^2 + y_ii \right)}
    \det_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not=z(y_r), r=0,\dots,k}}(\zeta_i(k) ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ \zeta_i(j)),
\end{multline*}
where $z(y_j)=\alpha_j(Ky_j+j)$ and where we denote $\vec z_{0,k}\coloneqq(z(y_0),\dots z(y_{k}))$. This is because similarly as in the previous proofs in this section we have $\binom{k+1}{2} - \sum_{j=0}^{k} b_j = \operatorname{inv}(\vec z_{0,k})$, and 
\begin{equation*}
     \prod_{j=1}^{n-1}p_+(j) 
        \prod_{i=0}^{k}
        \prod_{\ell=0}^{\alpha_iy_i-1}
        \frac{p_-(K\ell+k+\alpha_i i)}{p_+(K\ell+k+\alpha_i i)}=t^{-\frac{1}{2}\binom{n}{2} +\sum_{i=0}^{k} \left( \frac{1}{2}Ky_i^2 + y_ii \right)},
\end{equation*}
as the following simple calculations shows:
\begin{multline*}
-\sum_{j=1}^{n-1}\frac{j}{2}+\sum_{i=0}^k\sum_{\ell=0}^{\alpha_iy_i-1}\left(K\ell+k+\alpha_i i\right)=-\frac{1}{2}\binom{n}{2} + \sum_{i=0}^{k} K\binom{|y_i|}{2} + |y_i|k +y_ii \\= 
-\frac{1}{2}\binom{n}{2} +\sum_{i=0}^{k} \left( \frac{1}{2}Ky_i^2 + y_ii \right).
\end{multline*}
Inserting this into our expression from before yields that
\begin{equation*}
    P_{(k^n)}^{\mathrm{B}_n}(X;t,1)=2\sum_{\substack{(y_0,\dots,y_{ k}) \in\mathbb{Z}^{k +1} \\ y_0,y_k \geq 0}}
        (-1)^{\binom{n}{2}+\operatorname{inv}(\vec z_{0,k})+|y|} t^{\sum_{i=0}^{k} \left( \frac{1}{2}Ky_i^2 + y_ii \right)}
    \frac{\det\limits_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not=z(y_r), r=0,\dots,k}}(\zeta_i(k) ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ \zeta_i(j))}{\det\limits_{1 \le i,j \le n}(\zeta_i(n-j))}.
\end{equation*}

Now consider the determinant $$\det\limits_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not=z(y_r), r=0,\dots,k}}(\zeta_i(k) ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ \zeta_i(j)),$$
in the numerator. The first column of the determinant is $\zeta_i(k)$. However, if $z(y_i)\ne k$ for all $i$ then there is a second column of the same form, and hence the determinant vanishes. An elementary algebraic manipulation reveals that $z(y_i) = k$ if and only if $i=k$ and $y_k\in\{0,-1\}$. Since $y_k\ge0$, we have only one option and may assume, from now on, that $y_k=0$. Note that then
\begin{equation*}
    \operatorname{inv}(\vec z_{0,k})=\operatorname{inv}((z(y_0),\dots,z(y_{k-1}),k)=\operatorname{inv}(\vec z_{0,k-1})+|\{j\in[0,k-1]\mid k<z(y_j)\}|.
\end{equation*}
Now reorder the columns of the determinant to be in increasing order with respect to the argument of $\zeta_i$. The only misplaced column is the first. This introduces a sign of $$(-1)^{k-|\{j\in[0,k-1]\mid z(y_j)< k\}|}=(-1)^{|\{j\in[0,k-1]\mid k<z(y_j)\}|},$$
as there are $k-|\{j\in[0,k-1]\mid z(y_j)< k\}|$ many columns after the first column of our matrix where the argument of $\zeta_i$ is smaller than $k$. Thus we have arrived at
\begin{equation*}
    P_{(k^n)}^{\mathrm{B}_n}(X;t,1)=2\sum_{\substack{(y_0,\dots,y_{k-1}) \in\mathbb{Z}^{k } \\ y_0 \geq 0}}
        (-1)^{\binom{n}{2}+\operatorname{inv}(\vec z_{0,k-1})+|y|} t^{\sum_{i=0}^{k-1} \left( \frac{1}{2}Ky_i^2 + y_ii \right)}
    \frac{\det\limits_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not=z(y_r), r=0,\dots,k-1}}(\zeta_i(j))}{\det\limits_{1 \le i,j \le n}(\zeta_i(n-j))}.
\end{equation*}

To be able to use the Weyl character formula of type $\mathrm{D}_n$ \eqref{eq: Weyl character formula type D} and Corollary~\ref{cor:useful.complementary}, we define a vector $\nu\coloneqq(\nu_1\dots,\nu_k)$ by
\[
\nu_i := z(y_{i-1})=\alpha_{i-1}(Ky_{i-1}+i-1) = |Ky_{i-1}+i-1|
\]
for $i=1,\ldots,k$
and use $\operatorname{inv}(\vec z_{0,k-1}) = \operatorname{inv}(\nu)$
to reindex the sum by simultaneously setting $y_i\rightarrow y_{i+1}$ for $i=0,\dots k-1$ and write it as a sum over tuples $(y_1,\ldots,y_k)\in \mathbb{Z}^k$. We obtain
\begin{equation*}
    P_{(k^n)}^{\mathrm{B}_n}(X;t,1)
  =  
  2\sum_{\substack{(y_1, \ldots, y_k)\in\mathbb{Z}^k\\ y_1\ge0}}
    (-1)^{\binom{n}{2} + \operatorname{inv}(\nu) + |y|}
    t^{\sum_{i=1}^{k} \left( \frac{1}{2}Ky_i^2 + y_i(i-1) \right)}
  \frac{\det\limits_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not=\nu_r, r=1,\dots,k}}(\zeta_i(j))
  }{\det\limits_{1 \le i, j \le n}(\zeta_i(n-j))}.
\end{equation*}
By the Weyl character formula of type $\mathrm{D}_n$ \eqref{eq: Weyl character formula type D} and by Corollary~\ref{cor:useful.complementary}, we see that
$$(-1)^{\binom{n}{2}}\frac{\det\limits_{\substack{1\le i\le n \\0 \le j\le k+n-1 \\ j \not=\nu_r, r=1,\dots,k}}(\zeta_i(j))
  }{\det\limits_{1 \le i, j \le n}(\zeta_i(n-j))}=\frac{(1+[\lambda(\nu)_n=0])}{2}o^{\textup{even}}_{\lambda(\nu)}(X).$$
  Note that the condition for the matrix in the numerator to be a square matrix is precisely the condition that the $y_a$'s corresponding $\nu_a$'s are inside $\{0,\dots,n+k-1\}$ and are all different.
Plugging this into our expression from before we obtain
\[
    P_{(k^n)}^{\mathrm{B}_n}(X;t,1)
  =  
  \sum_{\substack{(y_1, \ldots, y_k)\in\mathbb{Z}^k\\ y_1\ge0}}
  (1+[\lambda(\nu)_n=0])
    (-1)^{\operatorname{inv}(\nu) + |y|}
    t^{\sum_{i=1}^{k} \left( \frac{1}{2}Ky_i^2 + y_i(i-1) \right)}
  o^{\textup{even}}_{\lambda(\nu)}(X),
\]
where we sum over all $y\in\mathbb{Z}^k$ such that the corresponding $\nu_a$'s are inside $\{0,\dots,n+k-1\}$ and are all different. 

To finish the proof, we need to make use of a symmetry property of our summands. We first claim that $\lambda(\nu)_n=0$ if $y_1\neq 0$. By unravelling Lemma~\ref{lem:flip}, we have
\[\lambda(\nu)_n = k - \ell(\mathrm{sort}(\nu)-\rho_k)
  = k - |\{i\in[k]\mid\mathrm{sort}(\nu)_i > k-i\}|.
\]
Now note that $\mathrm{sort}(\nu)$ is a strict partition, because $(\nu_1=z(y_0),\dots,\nu_k=z(y_{k-1}))$ are all located on different connected components, hence are all different. Therefore the only way how $\ell(\mathrm{sort}(\nu)-\rho_k)\neq k$ and subsequently $\lambda(\nu)_n\neq 0$ is when $\nu_1=0$, which, if we assume $y_1\geq 0$, is the case if and only if $y_1=0$. Thus $\lambda(\nu)_n=0$ unless $y_1=0$. 

Denoting $$S(y_1,\ldots,y_k) \coloneqq (-1)^{\operatorname{inv}(\nu) + |y|}
    t^{\sum_{i=1}^{k} \left( \frac{1}{2}Ky_i^2 + y_i(i-1) \right)}
  o^{\textup{even}}_{\lambda(\nu)}(X),$$ we get the following symmetry property of our summands:
$$S(-y_1,y_2,\ldots,y_k) = S(y_1,y_2,\ldots,y_k).$$
This follows from the fact that $y_1$, the previous $y_0$, only contributes to $\nu_1=z(y_0)$ and that $z(y_0)=\alpha_0Ky_0=z(-y_0)$, thus $\lambda(\nu)$ is symmetric in $y_1$. The symmetry of the exponent of $t$ follows directly from the fact that the $i=1$ summand in the exponent of $t$ is given by $\frac{1}{2}Ky_1^2$ and clearly symmetric in $y_1$.

Combining these two observations we see that
\begin{align*}
    P_{(k^n)}^{\mathrm{B}_n}(X;t,1)
  &=  
  \sum_{\substack{(y_1, \ldots, y_k)\in\mathbb{Z}^k\\ y_1\ge0}}
  (1+[\lambda(\nu)_n=0]) S(y_1,y_2,\ldots,y_k)\\
  &=  
  \sum_{\substack{(y_1, \ldots, y_k)\in\mathbb{Z}^k\\ y_1\ge0}}
  (1+[y_1\ne 0]) S(y_1,y_2,\ldots,y_k)\\
  &=  
  \sum_{\substack{(y_1, \ldots, y_k)\in\mathbb{Z}^k\\ y_1\ge0}}
  S(y_1,y_2,\ldots,y_k)
+
  \sum_{\substack{(y_1, \ldots, y_k)\in\mathbb{Z}^k\\ y_1 > 0}}
  S(y_1,y_2,\ldots,y_k)\\  &=  
  \sum_{\substack{(y_1, \ldots, y_k)\in\mathbb{Z}^k\\ y_1\ge0}}
  S(y_1,y_2,\ldots,y_k)
+
  \sum_{\substack{(y_1, \ldots, y_k)\in\mathbb{Z}^k\\ y_1 < 0}}
  S(y_1,y_2,\ldots,y_k)\\  &=  
  \sum_{(y_1, \ldots, y_k)\in\mathbb{Z}^k}
  S(y_1,y_2,\ldots,y_k)\\&=\sum_{(y_1, \ldots, y_k)\in\mathbb{Z}^k}(-1)^{\operatorname{inv}(\nu) + |y|}
    t^{\sum_{i=1}^{k} \left( \frac{1}{2}Ky_i^2 + y_i(i-1) \right)}
  o^{\textup{even}}_{\lambda(\nu)}(X),
\end{align*}
which is the desired expression.

Let $\nu_a = |Ky_a + a-1|$ as in~\eqref{thm-type-b-1-char}. 
Unravelling the definitions preceding Lemma~\ref{lem:flip}, we have
\begin{multline*}
\lambda(\nu)'_i = (\mathrm{sort}(\nu) - \rho_k)^{\square n^k}_i = 
n - (\mathrm{sort}(\nu) - \rho_k)_{k+1-i} =
n - \mathrm{sort}(\nu)_{k+1-i} + i -1\\
= n - |Ky_{\sigma(i)} + \sigma(i)-1| + i-1\,,
\end{multline*}
where $\sigma$ is the permutation that sorts $\nu$ into increasing order.

We apply the dual Jacobi--Trudi identity of type $\mathrm{D}_n$ \eqref{eq: dual JT type D} to the formula of ~\eqref{thm-type-b-1-char} to get
\begin{multline*}
P_{(k^n)}^{\mathrm{B}_n}(X;t,1)\\=\frac{1}{2} 
\sum_{{(y_1, \ldots, y_k)\in\mathbb{Z}^k}} 
(-1)^{|y|+\mathrm{inv}(\nu)}
t^{\sum_{j=1}^k \left( \frac{1}{2}K y_j^2 + (j-1)y_j \right)}
\det_{1\leq i,j\leq k}( \dot{e}_{\lambda(\nu)'_i-i+j}
+ 
\dot{e}_{\lambda(\nu)'_i-i-j+2}).
\end{multline*}
By the assumption in Theorem \ref{thm-b-char}, the sum ranges over all vectors $y\in\mathbb{Z}^k$ such that $\nu_1,\dots,\nu_k\in[0,n+k-1]$ are all different elements. By Lemma \ref{lem: handling the summation range} the determinant on the right hand side of this sum vanishes outside of this range of summation, hence we can extend the sum, to a sum over all $y\in\mathbb{Z}^k$. 

Plugging in the expression for $\lambda(\nu)'_i$ that we got before, this determinant is
\[
\det_{1\leq i,j\leq k}\left(
\dot{e}_{
n - |Ky_{\sigma(i)} + \sigma(i) - 1|  + j - 1
} +
\dot{e}_{
n - |Ky_{\sigma(i)} + \sigma(i) - 1| - j + 1
}\right).
\]
Now we rearrange the rows of the matrix by the permutation $\sigma^{-1}$. This cancels the factor $\operatorname{sgn}(\sigma) = (-1)^{\mathrm{inv}(\nu)}$, as $\sigma$ is the permutation that sorts $\nu$ in increasing order, hence the sign is given by the number of inversions of $\nu$. The matrix becomes
\[
\det_{1\leq i,j\leq k}\left(
\dot{e}_{
n - |Ky_{i} + i - 1| + j - 1
} +
\dot{e}_{
n - |Ky_{i} + i - 1| - j + 1
}\right).
\]
We distinguish cases according to the sign of $y_i$ and fix some $1\leq i,j\leq k$.
If $y_i$ is non-negative, we use the formula
$\dot{e}_{n+r} = \dot{e}_{n-r}$ to get 
\begin{multline*}
\dot{e}_{
n - |Ky_{i} + i - 1| + j - 1
} +
\dot{e}_{
n - |Ky_{i} + i - 1| - j + 1
}\\ = 
\dot{e}_{
n - Ky_{i} - i + j 
} +
\dot{e}_{
n - Ky_{i} - i - j + 2
} =
\dot{e}_{
n + Ky_{i} + i - j 
} +
\dot{e}_{
n + Ky_{i} + i + j - 2
}\,.
\end{multline*}
If $y_i$ is negative, we immediately obtain
\begin{equation*}
\dot{e}_{
n - |Ky_{i} + i - 1| + j - 1
} +
\dot{e}_{
n - |Ky_{i} + i - 1| - j + 1
} = 
\dot{e}_{
n + Ky_{i} + i + j - 2
} +
\dot{e}_{
n + Ky_{i} + i - j
}.
\end{equation*}
Replacing $y_i$ by $-y_i$, and transposing the matrix
we have arrived at
    \[
    \frac{1}{2}
\sum_{{(y_1, \ldots, y_k)\in\mathbb{Z}^k}}
(-1)^{|y|}
t^{\sum_{j=1}^k \left( \frac{1}{2}K y_j^2 - (j-1)y_j \right)}
\det_{1 \le i,j \le k}
\left(
\dot{e}_{\,n-i+j-K y_j}
+
\dot{e}_{\,n+i+j- Ky_j-2}
\right).\]
By Lemma \ref{lem: handling the summation range}, the support of this sum is finite, so extending the sum to a finite $S_k$ invariant subset containing the support, by Lemma~\ref{lem:powery}, we get that this is equal to the right-hand side of~\eqref{thm-type-b-1}.

Setting $s_1=0$ and $s_2=0$ in the expression of Lemma~\ref{magical manipulation} we get 

\begin{multline*}
    P_{(k^n)}^{\mathrm{C}_n}(X;t,0)= \frac{\sqrt{t}^{\binom{n}{2}}}{2}
    \prod_{i=1}^nx_i^{n-1}\prod_{1\leq i<j\leq n}\frac{1}{(1-x_ix_j)(x_i-x_j)}\\\times\det_{1\le i,j\le n}\left(\frac{1}{1-x_i^2}
    \left((\sqrt{t})^{j-1}x_i^{j-1-k}+
    (\sqrt{t})^{-j+1}x_i^{-j+1-k}\right)\right.\\\left.-\frac{x_i^2}{1-x_i^2}
    \left((\sqrt{t})^{j-1}x_i^{-j+1+k}
    +(\sqrt{t})^{-j+1}x_i^{j-1+k}\right)\right)\\=
    \frac{\sqrt{t}^{\binom{n}{2}}}{2}
    \prod_{i=1}^n\frac{x_i^{n-1}}{x_i^2-1}\prod_{1\leq i<j\leq n}\frac{1}{(1-x_ix_j)(x_i-x_j)}\\\times\det_{1\le i,j\le n}
    \left((\sqrt{t})^{j-1}\left(x_i^{-j+3+k}-x_i^{j-1-k}\right)+
    (\sqrt{t})^{-j+1}\left(x_i^{j+1+k}-x_i^{-j+1-k}\right)\right).
\end{multline*}
 We identify the Weyl denominator of type \ref{eq: Denom type C} up to a factor of $\prod_{i=1}^nx_i^{-1}$, which we distribute over the determinant, and a sign $(-1)^{\binom{n}{2}}$, to write our expression as
 \begin{multline*}
     \frac{(-\sqrt{t})^{\binom{n}{2}}}{2}
    \det_{1\le i,j\le n}
    \left((\sqrt{t})^{j-1}\left(x_i^{-j+2+k}-x_i^{j-2-k}\right)+
    (\sqrt{t})^{-j+1}\left(x_i^{j+k}-x_i^{-j-k}\right)\right)\\\times 1/\det_{1\leq i,j\leq n}\left(x_i^{n-j+1}-\bar{x}^{n-j+1}\right).
 \end{multline*}
Using our shorthand notation $\eta_i(m)$ for the expression $ x_i^{m} - \bar{x}_i^{m}$ from before, we observe that the first column is given by $2\eta_i(k+1)$. Factoring out this $2$ from the first column by the multilinearity of the determinant, we can write the above as
 \[
 P_{(k^n)}^{\mathrm{C}_n}(X;t,0)
  =  
  (-\sqrt{t})^{\binom{n}{2}}
  \frac{\det\limits_{\substack{1 \le i \le n\\ 1 \le j < n}}(
  \eta_i(k+1) ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ (\sqrt{t})^{-j}\eta_i(k+1+j) +(\sqrt{t})^{j}\eta_i(k+1-j)
  )}{\det\limits_{1 \le i, j \le n}(\eta_i(n-j+1))}\,.
 \]
We invoke Lemma~\ref{lem: noodle-doodle expansion 2.3a} with $\eta_i(a)=x_i^{a} - \bar{x}_i^{a}$, $p_{\pm}(j) = (\sqrt{t})^{\mp j}$ and $K=2k+2$ to obtain that
\begin{multline*}
    \det\limits_{\substack{1 \le i \le n\\ 1 \le j < n}}(
  \eta_i(k+1) ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ (\sqrt{t})^{-j}\eta_i(k+1+j) +(\sqrt{t})^{j}\eta_i(k+1-j)
  )\\=\sum_{\substack{(y_0,\dots,y_{k+1}) \in\mathbb{Z}^{k +2} \\ y_0,y_{k+1} \geq 0}}
        (-1)^ {\sum_{i=0}^{k+1} [y_i<0] + \operatorname{inv}(\vec z_{0,k+1})}t^{-\frac{1}{2}\binom{n}{2} +\sum_{i=0}^{k+1} \left( \frac{1}{2}Ky_i^2 + y_ii \right)}
        \\\times \det_{\substack{1\le i\le n \\0 \le j\le k+n \\ j \not=z(y_r), r=0,\dots,k+1}}(\eta_i(k+1) ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ \eta_i(j)),
\end{multline*}
where $z(y_j)=\alpha_j(Ky_j+j)$ and we denote $\vec z_{0,k+1}\coloneqq(z(y_0),\dots,z(y_{k+1}))$. This is because as in the proofs of the previous section we have $\binom{k+2}{2} - \sum_{j=0}^{k+1} b_j = \operatorname{inv}(\vec z_{0,k+1})$ and furthermore
\begin{equation*}
    \prod_{j=1}^{n-1}p_+(j) 
        \prod_{i=0}^{k+1}
        \prod_{\ell=0}^{\alpha_iy_i-1}
        \frac{p_-(K\ell+k+1+\alpha_i i)}{p_+(K\ell+k+1+\alpha_i i)}=t^{-\frac{1}{2}\binom{n}{2} +\sum_{i=0}^{k+1} \left( \frac{1}{2}Ky_i^2 + y_ii \right)},
\end{equation*}
as the following simple calculation shows
\begin{multline*}
    -\sum_{j=1}^{n-1}\frac{j}{2}+\sum_{i=0}^{k+1}\sum_{\ell=0}^{\vert y_i\vert-1}(K\ell+k+1+\alpha_i i)=-\frac{1}{2}\binom{n}{2} + \sum_{i=0}^{k+1} \left(K\binom{|y_i|}{2} + |y_i|(k+1) +y_ii\right) \\= 
-\frac{1}{2}\binom{n}{2} +\sum_{i=0}^{k+1} \left( \frac{1}{2}Ky_i^2 + y_ii \right).
\end{multline*} Inserting this into our expression from before we get that
\begin{multline*}
    P_{(k^n)}^{\mathrm{C}_n}(X;t,0)=\sum_{\substack{(y_0,\dots,y_{k+1}) \in\mathbb{Z}^{k +2} \\ y_0,y_{k+1} \geq 0}}
        (-1)^ {\binom{n}{2}+\sum_{i=0}^{k+1} [y_i<0] + \operatorname{inv}(\vec z_{0,k+1})}t^{ \sum_{i=0}^{k+1} \left( \frac{1}{2}Ky_i^2 + y_ii \right)}
        \\\times \frac{\det\limits_{\substack{1\le i\le n \\0 \le j\le k+n \\ j \not=z(y_r), r=0,\dots,k+1}}(\eta_i(k+1) ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ \eta_i(j))}{\det\limits_{1 \le i, j \le n}(\eta_i(n-j+1))}.
\end{multline*}

Now consider the determinant
$$\det\limits_{\substack{1\le i\le n \\0 \le j\le k+n \\ j \not=z(y_r), r=0,\dots,k+1}}(\eta_i(k+1) ~\mathbin{\raisebox{-.18em}{$\vdots$}}~ \eta_i(j)),$$
from the numerator and note that if $y_{k+1}\ne 0$, then the determinant has two equal columns and thus vanishes. Therefore, we can assume $y_{k+1}=0$ and so $z(y_{k+1})=k+1$ from now on. If $y_0\ne0$, then the matrix has a column of zeros and thus vanishes, so we can assume $y_0=0$ and $z(y_0)=0$ from now on too. Note that then
\begin{multline*}
    \operatorname{inv}(\vec z_{0,k+1})=\operatorname{inv}(0,z(y_1),\dots,z(y_k),k+1)\\=\operatorname{inv}(\vec z_{1,k})+\vert\{j\in[1,k]\mid z(y_j)<0\}+\vert\{j\in[1,k]\mid k+1<z(y_j)\}\\=\operatorname{inv}(\vec z_{1,k})+\vert\{j\in[1,k]\mid k+1<z(y_j)\},
\end{multline*}
as $z(y_j)\geq 0$ for all $1\leq j\leq k$. We reorder the columns of the matrix to be in increasing order with respect to the argument of $\eta_i$. The only misplaced column is the first one, and this introduces a sign of 
$$(-1)^{k-\vert\{j\in[1,k]\mid z(y_j)<k+1\}\vert}=(-1)^{\vert\{j\in[1,k]\mid k+1<z(y_j)\}},$$
as there are $k-\vert\{j\in[1,k]\mid z(y_j)<k+1\}\vert$ many columns after the first column of our matrix where the argument of $\eta_i$ is smaller than $k+1$. Thus we have arrived at
\begin{equation*}
    P_{(k^n)}^{\mathrm{C}_n}(X;t,0)=\sum_{(y_1,\dots,y_{k}) \in\mathbb{Z}^{k}}
        (-1)^ {\binom{n}{2}+ \operatorname{inv}(\vec z_{1,k})+\sum_{j=1}^k [y_j<0]}t^{ \sum_{i=1}^{k} \left( \frac{1}{2}Ky_i^2 + y_ii \right)} \frac{\det\limits_{\substack{1\le i\le n \\1 \le j\le k+n \\ j \not=z(y_r), r=1,\dots,k}}(\eta_i(j))}{\det\limits_{1 \le i, j \le n}(\eta_i(n-j+1))}.
\end{equation*}


To be able to use the Weyl character formula of type $\mathrm{C}_n$ \eqref{eq: Weyl character formula type C} and Corollary~\ref{cor:useful.complementary}, we define a vector $\nu\coloneqq (\nu_1,\dots,\nu_k)$ by
$$\nu_i\coloneqq z(y_i)-1=\alpha_i(Ky_i+i)-1=\vert Ky_i+i\vert-1$$
and observe that $\operatorname{inv}(\vec z_{1,k})=\operatorname{inv}(\nu)$. This allows us to rewrite our expression as

\[
    P_{(k^n)}^{\mathrm{C}_n}(X;t,0)=\sum_{(y_1,\ldots,y_{k})\in\mathbb{Z}^{k}}
    (-1)^{\binom{n}{2}+ \operatorname{inv}(\nu)+\sum_{j=1}^k [y_j<0] }
    t
    ^{\sum_{i=1}^{k} \left(\frac{1}{2}Ky_i^2 + y_ii \right)}
    \frac{\det\limits_{\substack{1\le i\le n \\1 \le j\le k+n \\ j \not=\nu_r+1, r=1,\dots,k}}(\eta_i(j))}{\det\limits_{1 \le i,j \le n}(\eta_i(n-j+1))}  
\]

By the Weyl character formula of type $\mathrm{C}_n$ \eqref{eq: Weyl character formula type C} and Corollary~\ref{cor:useful.complementary} we have that
$$(-1)^{\binom{n}{2}}\frac{\det\limits_{\substack{1\le i\le n \\1 \le j\le k+n \\ j \not=\nu_r+1, r=1,\dots,k}}(\eta_i(j))}{\det\limits_{1 \le i,j \le n}(\eta_i(n-j+1))}=sp_{\lambda(\nu)}(X).$$
Note that the condition for the matrix in the numerator to be a square matrix is precisely the condition that the $y_a$'s corresponding $\nu_a$'s are inside $\{0,\dots,n+k-1\}$ and are all different. Inserting into our expression from above yields
\[
P_{(k^n)}^{\mathrm{C}_n}(X;t,0)
= 
    \sum_{(y_1,\ldots,y_{k})\in\mathbb{Z}^{k}}
    (-1)^{ \operatorname{inv}(\nu)+\sum_{j=1}^k [y_j<0]}
    t
    ^{\sum_{i=1}^{k} \left( \frac{1}{2}Ky_i^2 + y_ii \right)}sp_{\lambda(\nu)}(X), 
\]
where we sum over all $y\in\mathbb{Z}^k$ such that the corresponding $\nu_a$'s are inside $\{0,\dots,n+k-1\}$ and are all different, as claimed.

Let $\nu_a = |Ky_a + a| - 1$ as in~\eqref{thm-type-c-0-char}. 
Unravelling the definitions preceding Lemma~\ref{lem:flip} we have
\begin{multline*}
\lambda(\nu)'_i = (\mathrm{sort}(\nu) - \rho_k)^{\square n^k}_i = 
n - (\mathrm{sort}(\nu) - \rho_k)_{k+1-i} =
n - \mathrm{sort}(\nu)_{k+1-i} + i -1\\
= n - |Ky_{\sigma(i)} + \sigma(i)| + i\,,
\end{multline*}
where $\sigma$ is the permutation that sorts $\nu$ into increasing order.

We apply the dual Jacobi--Trudi identity of type $\mathrm{C}_n$ \eqref{eq: dual JT type C} to the formula of ~\eqref{thm-type-c-0-char} to get
\[
P_{(k^n)}^{\mathrm{C}_n}(X;t,0)=
\sum_{y \in \mathbb{Z}^k}
(-1)^{\mathrm{inv}(\nu)+\sum_{j=1}^k [y_j<0]}
t^{\sum_{j=1}^k \left( \frac{1}{2}Ky_j^2 + jy_j \right)}
\det_{1\leq i,j\leq k}(\dot{e}_{\lambda(\nu)'_i-i+j}
- 
\dot{e}_{\lambda(\nu)'_i-i-j}).
\]
By the assumption in Theorem \ref{main-type-c}, the sum ranges over all vectors $y\in\mathbb{Z}^k$ such that $\nu_1,\dots,\nu_k\in[0,n+k-1]$ are all different elements. By Lemma \ref{lem: handling the summation range} the determinant on the right hand side of this sum vanishes outside of this range of summation, hence we can extend the sum, to a sum over all $y\in\mathbb{Z}^k$. 

Plugging in the expression for $\lambda(\nu)'_i$, from before this determinant is equal to
\[
\det_{1\leq i,j\leq k}(
\dot{e}_{
n - |Ky_{\sigma(i)} + \sigma(i)|  + j
} -
\dot{e}_{
n - |Ky_{\sigma(i)} + \sigma(i)| - j
}).
\]
Now we rearrange the rows of the matrix by the permutation $\sigma^{-1}$. This cancels the factor $\operatorname{sgn}(\sigma) = (-1)^{\mathrm{inv}(\nu)}$, as $\sigma$ is the permutation that sorts $\nu$ in increasing order, hence the sign is given by the number of inversions of $\nu$. The matrix becomes
\[
\det_{1\leq i,j\leq k}(
\dot{e}_{
n - |Ky_{i} + i| + j 
} -
\dot{e}_{
n - |Ky_{i} + i| - j 
}).
\]
We distinguish cases according to the sign of $y_i$ and fix some $1\leq i,j\leq k$.
If $y_i$ is non-negative, we use the formula $\dot{e}_{n+r}=\dot{e}_{n-r}$  to get
\begin{equation*}\dot{e}_{
n - |Ky_{i} + i| + j 
} -
\dot{e}_{
n - |Ky_{i} + i| - j 
}= 
\dot{e}_{
n - Ky_{i} - i + j
} -
\dot{e}_{
n - Ky_{i} - i - j
} =
\dot{e}_{
n + Ky_{i} + i - j
} -
\dot{e}_{
n + Ky_{i} + i + j 
}\,.
\end{equation*}
If $y_i$ is negative, one directly gets
\begin{equation*}
\dot{e}_{
n - |Ky_{i} + i| + j 
} -
\dot{e}_{
n - |Ky_{i} + i| - j 
}=
-(
\dot{e}_{
n + Ky_{i} + i - j
} -
\dot{e}_{
n + Ky_{i} + i + j 
})\,.
\end{equation*}
Pulling this sign out of the determinant using the multilinearity we obtain an additional factor of $(-1)^{\sum_{j=1}^k [y_j<0]}$. Replacing $y_i$ by $-y_i$ and then transposing the matrix yields
\[
P_{(k^n)}^{\mathrm{C}_n}(X;t,0)=
\sum_{y \in \mathbb{Z}^k}
t^{\sum_{j=1}^k \left( \frac{1}{2}K y_j^2 - jy_j \right)}
\det_{1 \le i,j \le k}
\left(
\dot{e}_{\,n-i+j-K y_j}
-
\dot{e}_{\,n+i+j- Ky_j}
\right).\]
By Lemma \ref{lem: handling the summation range}, the support of this sum is finite, so extending the sum to a finite $S_k$ invariant subset containing the support, by Lemma~\ref{lem:powery}, we get that this is equal to the right-hand side of the sought expression.

Set $s_1=\sqrt{t}$ and $s_2=-\sqrt{t}$ in the expression of Lemma~\ref{magical manipulation} to get
    \begin{multline*}
    P_{(k^n)}^{\mathrm{C}_n}(X;t,t)= \frac{(\sqrt{t})^{\binom{n}{2}}}{2}
    \prod_{i=1}^nx_i^{n-1}\prod_{1\leq i<j\leq n}\frac{1}{(1-x_ix_j)(x_i-x_j)}\\\times\det_{1\le i,j\le n}\left(\frac{(1-\sqrt{t}x_i)(1+\sqrt{t}x_i)}{1-x_i^2}
    \left((\sqrt{t})^{j-1}x_i^{j-1-k}+
    (\sqrt{t})^{-j+1}x_i^{-j+1-k}\right)\right.\\\left.-\frac{(\sqrt{t}-x_i)(-\sqrt{t}-x_i)}{1-x_i^2}
    \left((\sqrt{t})^{j-1}x_i^{-j+1+k}
    +(\sqrt{t})^{-j+1}x_i^{j-1+k}\right)\right)\\
    =\frac{(\sqrt{t})^{\binom{n}{2}}}{2}
    \prod_{i=1}^n\frac{x_i^{n-1}}{x_i^2-1}\prod_{1\leq i<j\leq n}\frac{1}{(1-x_ix_j)(x_i-x_j)}\\\times\det_{1\le i,j\le n}\left((tx_i^2-1)\left((\sqrt{t})^{j-1}x_i^{j-1-k}+
