We identify the Weyl denominator of type \ref{eq: Denom type C} up to a factor of $\prod_{i=1}^nx_i^{-1}$, which we distribute over the determinant, and a sign $(-1)^{\binom{n}{2}}$, to write our expression as
\begin{multline*}
    \frac{(-\sqrt{t})^{\binom{n}{2}}}{2}\det_{1\le i,j\le n}\left((tx_i-\bar{x}_i)\left((\sqrt{t})^{j-1}x_i^{j-1-k}+
    (\sqrt{t})^{-j+1}x_i^{-j+1-k}\right)\right.\\\left.+(x_i-t\bar{x}_i)
    \left((\sqrt{t})^{j-1}x_i^{-j+1+k}
    +(\sqrt{t})^{-j+1}x_i^{j-1+k}\right)\right)/\det_{1\leq i,j\leq n}\left(x_i^{n-j+1}-\bar{x}^{n-j+1}\right).
\end{multline*}
Using our shorthand notation $\eta_j(m)$ for the expression $x_j^m-\bar{x}_j^m$ again, we can rewrite this expression as
\begin{multline*}
    \frac{(-\sqrt{t})^{\binom{n}{2}}}{2}\det_{1\le i,j\le n}\left((\sqrt{t})^{-j+1}\eta_i(k+j)
    -(\sqrt{t})^{j+1}\eta_i(k-j)
    \right.\\\left.-(\sqrt{t})^{-(j-2)+1}\eta_i(k+j-2)
    +(\sqrt{t})^{(j-2)+1}\eta_i(k-(j-2))\right)/\det_{1\leq i,j\leq n}\left(\eta_i(n-j+1)\right).
\end{multline*}
Now observe that the determinant in the numerator equals the following determinant, where we factored out the $2$ from the first column, since the first matrix can be obtained from the latter by applying elementary column operations $C_j \rightarrow C_j-C_{j-2}$ for $j=n,\dots, 3$,
\begin{multline*}
    2\det_{1\leq i,j\leq n}\left((\sqrt{t})^{-j+1}\eta_i(k+j)
    -(\sqrt{t})^{j+1}\eta_i(k-j)\right)\\=2(\sqrt{t})^n\det_{1\leq i,j\leq n}\left((\sqrt{t})^{-j}\eta_i(k+j)
    -(\sqrt{t})^{j}\eta_i(k-j)\right).
\end{multline*}
Therefore, our expression is equal to
\begin{equation*}
    P_{(k^n)}^{\mathrm{C}_n}(X;t,t)=(-1)^{\binom{n}{2}}(\sqrt{t})^{\binom{n}{2}+n}\frac{\det\limits_{1\leq i,j\leq n}\left((\sqrt{t})^{-j}\eta_i(k+j)
